// Give sample lessons real dates in the current Saturday-to-Friday week so each personal calendar is meaningful.
const demoNow=new Date();
const demoWeekStart=new Date(demoNow);demoWeekStart.setDate(demoNow.getDate()-((demoNow.getDay()+1)%7));
sample.schedule.forEach((item,index)=>{
  const lessonDate=new Date(demoWeekStart);lessonDate.setDate(demoWeekStart.getDate()+index);
  item.date=item.date||`${lessonDate.getFullYear()}-${String(lessonDate.getMonth()+1).padStart(2,'0')}-${String(lessonDate.getDate()).padStart(2,'0')}`;
  item.day=item.day||new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(lessonDate);
});


// Restore demo-only instructor entries after a page reload.
state.demoInstructors.forEach(item=>{if(!sample.instructors.some(x=>x.id===item.id))sample.instructors.push(item);});
// Refresh the local demo student list from IndexedDB so newly created test cases remain visible.
function hydrateSampleStudents(){if(!window.NasirData)return;if(NasirData.getMode()==='api'&&state.role!=='admin')return;NasirData.listStudents().then(items=>{sample.students=items.map(x=>({id:x.id,name:x.name,code:x.studentCode||x.code||'—',phone:x.phone||'—',course:x.course||'پایه سوم',status:x.status||'در حال بررسی',city:x.city||'',neighborhood:x.neighborhood||'',address:x.address||'',nationalId:x.nationalId||'',birthDate:x.birthDate||'',registrationDate:x.registrationDate||'',tuitionAmountToman:Number(x.tuitionAmountToman)||0,province:x.province||'تهران'}));if(['students','myStudents'].includes(state.page)||(state.role==='admin'&&['dashboard','schedule','reports','payments'].includes(state.page)))renderPage();}).catch(()=>{});}
hydrateSampleStudents();

function enterApp(role, name, userId) {
  state.role = role;
  state.name = String(name||'کاربر آزمایشی').trim() || 'کاربر آزمایشی';
  state.userId = userId || (role === 'student' ? 'demo-student-01' : role === 'instructor' ? 'demo-instructor-01' : 'demo-admin-01');
  state.profile = readDemoStore(`nasirDemoProfile:${state.userId}`, role==='student'&&state.userId==='demo-student-01'?readDemoStore('nasirDemoProfile',{}):{});
  state.page = 'dashboard';
  document.getElementById('loginScreen').classList.add('hidden');
  document.getElementById('appShell').classList.remove('hidden');
  updateUser(); renderNav(); renderPage(); if(role==='admin')hydrateSampleStudents(); hydrateRoleSchedule();
}
function updateLoginPrompt(){
  const role=document.querySelector('.role-option.active')?.dataset.role||'student';
  const label=document.getElementById('displayNameLabel'),input=document.getElementById('displayName'),hint=document.getElementById('loginNameHint'),signup=document.getElementById('studentSelfRegisterButton');
  const copy={student:['نام یا شماره موبایل','نام، شماره موبایل یا شماره پرونده ثبت‌شده را وارد کنید.','نام یا شماره موبایل خود را وارد کنید؛ شماره پرونده هم قابل استفاده است.'],instructor:['نام یا شماره موبایل مربی','نام یا شماره موبایل ثبت‌شده در فهرست مربیان را وارد کنید.','مثلاً حسین احمدی یا 0912xxxxxxxx'],admin:['نام مدیر آموزشگاه','ورود نمایشی مدیر آموزشگاه در این نسخه تستی.','نام مدیر آموزشگاه']};
  if(label)label.textContent=copy[role][0];if(input)input.placeholder=copy[role][2];if(hint)hint.textContent=copy[role][1];if(signup)signup.hidden=role!=='student';
}
function resolveLogin(){
  if(NasirData.getMode()==='api'){showToast('ورود واقعی با کد یک‌بارمصرف هنوز به سرور متصل نشده است؛ برای تست، حالت local را نگه دارید.');return;}
  const role=document.querySelector('.role-option.active')?.dataset.role||'student';
  const value=document.getElementById('displayName').value.trim();
  if(!value){showToast('اطلاعات ورود را وارد کنید.');return;}
  if(role==='admin'){enterApp('admin',value,'demo-admin-01');return;}
  if(role==='instructor'){
    const key=normalizeLookup(value);const instructor=sample.instructors.find(x=>normalizeLookup(x.name)===key||normalizeLookup(x.phone)===key||normalizeLookup(x.id)===key);
    if(!instructor){showToast('مربی با این نام در فهرست آزمایشی پیدا نشد. نام حسین احمدی یا مریم حسینی را امتحان کنید.');return;}
    enterApp('instructor',instructor.name,instructor.id);return;
  }
  NasirData.listStudents().then(students=>{
    const key=normalizeLookup(value);const matches=students.filter(x=>[x.name,x.studentCode,x.code,x.phone].some(v=>normalizeLookup(v)===key));
    if(matches.length===1){enterApp('student',matches[0].name,matches[0].id);return;}
    if(matches.length>1){showToast('چند پرونده مشابه پیدا شد؛ با شماره پرونده یا موبایل وارد شوید.');return;}
    showToast('پرونده‌ای با این مشخصات پیدا نشد. از گزینه ثبت‌نام هنرجوی جدید استفاده کنید.');
  }).catch(error=>showToast(error.message||'دریافت فهرست هنرجویان ممکن نشد.'));
}
let activeAvatarObjectUrl = null;
let avatarLoadToken = 0;
function profileAvatarDb(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('مرورگر از ذخیره‌سازی تصویر پشتیبانی نمی‌کند.'));return;}const request=window.indexedDB.open('nasir-profile-media',1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('avatars'))db.createObjectStore('avatars',{keyPath:'userId'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('باز کردن فضای عکس‌های پروفایل ممکن نشد.'));});}
function profileBlobToDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error||new Error('خواندن عکس ممکن نشد.'));reader.readAsDataURL(blob);});}
function profileDataUrlToBlob(value){try{const parts=String(value).split(',');const mime=(parts[0].match(/data:(.*?);base64/)||[])[1]||'image/jpeg';const binary=atob(parts[1]);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:mime});}catch(_){return null;}}
async function saveProfileAvatar(userId,blob){try{const db=await profileAvatarDb();try{await new Promise((resolve,reject)=>{const tx=db.transaction('avatars','readwrite');tx.objectStore('avatars').put({userId,blob,updatedAt:new Date().toISOString()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('ذخیره عکس انجام نشد.'));tx.onabort=()=>reject(tx.error||new Error('ذخیره عکس لغو شد.'));});}finally{db.close();}localStorage.removeItem(`nasirProfileAvatar:${userId}`);}catch(error){try{localStorage.setItem(`nasirProfileAvatar:${userId}`,await profileBlobToDataUrl(blob));}catch(_){throw new Error('فضای ذخیره عکس کافی نیست؛ یک تصویر کوچک‌تر انتخاب کنید.');}}}
async function readProfileAvatar(userId){try{const db=await profileAvatarDb();const record=await new Promise((resolve,reject)=>{const tx=db.transaction('avatars','readonly');const req=tx.objectStore('avatars').get(userId);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});db.close();if(record?.blob)return record.blob;}catch(_){}const fallback=localStorage.getItem(`nasirProfileAvatar:${userId}`);return fallback?profileDataUrlToBlob(fallback):null;}
async function deleteProfileAvatar(userId){if(window.indexedDB){const db=await profileAvatarDb();try{await new Promise((resolve,reject)=>{const tx=db.transaction('avatars','readwrite');tx.objectStore('avatars').delete(userId);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('حذف عکس انجام نشد.'));tx.onabort=()=>reject(tx.error||new Error('حذف عکس لغو شد.'));});}finally{db.close();}}localStorage.removeItem(`nasirProfileAvatar:${userId}`);}
function paintAvatar(node,url,initial){if(!node)return;node.classList.toggle('has-image',Boolean(url));if(url){const image=document.createElement('img');image.src=url;image.alt='عکس پروفایل';image.draggable=false;node.replaceChildren(image);}else{node.textContent=initial;}}
async function hydrateProfileAvatar(){const token=++avatarLoadToken,userId=state.userId;let blob=null;try{blob=await readProfileAvatar(userId);}catch(_){}if(token!==avatarLoadToken||userId!==state.userId)return;let url='';if(blob){try{url=blob instanceof Blob?URL.createObjectURL(blob):String(blob);}catch(_){url='';}}if(activeAvatarObjectUrl&&activeAvatarObjectUrl.startsWith('blob:'))URL.revokeObjectURL(activeAvatarObjectUrl);activeAvatarObjectUrl=url.startsWith('blob:')?url:null;const initial=(state.name||'ن').trim().charAt(0)||'ن';paintAvatar(document.getElementById('topAvatar'),url,initial);paintAvatar(document.getElementById('profileAvatar'),url,initial);const removeButton=document.getElementById('removeProfilePhotoButton');if(removeButton)removeButton.hidden=!url;const pickButton=document.getElementById('profilePhotoPickButton');if(pickButton){pickButton.title=url?'تغییر عکس پروفایل':'افزودن عکس پروفایل';pickButton.setAttribute('aria-label',pickButton.title);}}
async function optimizeProfileAvatar(file){const allowed=['image/jpeg','image/png','image/webp'];if(!file||!allowed.includes(file.type))throw new Error('لطفاً یک تصویر JPG، PNG یا WebP انتخاب کنید.');if(file.size>8*1024*1024)throw new Error('حجم عکس باید کمتر از ۸ مگابایت باشد.');let source=null,objectUrl='';try{if(typeof createImageBitmap==='function'){source=await createImageBitmap(file);}else{objectUrl=URL.createObjectURL(file);source=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('باز کردن تصویر ممکن نشد.'));img.src=objectUrl;});}const width=source.width||source.naturalWidth,height=source.height||source.naturalHeight;if(!width||!height)throw new Error('ابعاد تصویر معتبر نیست.');const size=Math.min(width,height),sx=(width-size)/2,sy=(height-size)/2,canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('پردازش تصویر در این مرورگر ممکن نیست.');ctx.drawImage(source,sx,sy,size,size,0,0,512,512);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.88));if(!blob)blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(!blob)throw new Error('آماده‌سازی تصویر ناموفق بود.');return blob;}finally{if(source&&typeof source.close==='function')source.close();if(objectUrl)URL.revokeObjectURL(objectUrl);}}
function wireProfilePhotoControls(){const input=document.getElementById('profilePhotoInput'),remove=document.getElementById('removeProfilePhotoButton');if(input&&!input.dataset.wired){input.dataset.wired='true';input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;input.disabled=true;try{const blob=await optimizeProfileAvatar(file);await saveProfileAvatar(state.userId,blob);await hydrateProfileAvatar();showToast('عکس پروفایل با موفقیت ذخیره شد.');}catch(error){showToast(error.message||'ذخیره عکس پروفایل ممکن نشد.');}finally{input.disabled=false;input.value='';}});}if(remove&&!remove.dataset.wired){remove.dataset.wired='true';remove.addEventListener('click',async()=>{remove.disabled=true;try{await deleteProfileAvatar(state.userId);await hydrateProfileAvatar();showToast('عکس پروفایل حذف شد.');}catch(error){showToast(error.message||'حذف عکس پروفایل ممکن نشد.');}finally{remove.disabled=false;}});}}
function updateUser(){
  document.getElementById('topUserName').textContent = state.name;
  document.getElementById('topUserRole').textContent = roleLabels[state.role];
  document.getElementById('topAvatar').textContent = state.name.trim().charAt(0) || 'ن';
  hydrateProfileAvatar();
}
function renderNav(){
  const nav=document.getElementById('sideNav');
  nav.innerHTML=navByRole[state.role].map(([id,label,ico])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}">${icon(ico)}<span>${label}</span>${id==='announcements'?'<small class="nav-count">۲</small>':''}</button>`).join('');
  nav.querySelectorAll('[data-page]').forEach(btn=>btn.addEventListener('click',()=>goPage(btn.dataset.page)));
}
function goPage(page){if(!canAccessPage(page)){showToast('شما به این بخش دسترسی ندارید.');return;}state.page=page;renderNav();renderPage();closeSidebar();window.scrollTo({top:0,behavior:'smooth'});}
function closeSidebar(){document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebarScrim').classList.remove('show');}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow"><i></i> پنل ${roleLabels[state.role]}</span><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`;}
function stats(items){return `<div class="stats-grid">${items.map(x=>`<article class="stat-card"><div class="stat-icon ${x.tone}">${icon(x.icon)}</div><div class="stat-text"><span>${x.label}</span><strong>${x.value}</strong><small>${x.note}</small></div></article>`).join('')}</div>`;}
function getAllScheduleItems(){const base=NasirData.getMode()==='api'?(state.remoteScheduleItems||[]):[...sample.schedule,...state.demoSchedules];return base.map(item=>{
  const inferredStudent=sample.students.find(x=>item.studentName&&normalizeLookup(x.name)===normalizeLookup(item.studentName));
  const inferredInstructor=sample.instructors.find(x=>item.instructorName&&normalizeLookup(x.name)===normalizeLookup(item.instructorName));
  return {...item,studentId:item.studentId||inferredStudent?.id||'',instructorId:item.instructorId||inferredInstructor?.id||''};
});}
function getScheduleItems(){
  let items=getAllScheduleItems();
  if(state.role==='student')items=items.filter(x=>x.studentId===state.userId);
  else if(state.role==='instructor')items=items.filter(x=>x.instructorId===state.userId);
  return items.sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||String(a.time||'').localeCompare(String(b.time||'')));
}
function getAssignedStudentIds(){if(NasirData.getMode()==='api')return (state.instructorStudents||[]).map(x=>x.id);return [...new Set(getAllScheduleItems().filter(x=>x.instructorId===state.userId).map(x=>x.studentId).filter(Boolean))];}
function getAssignedStudents(){if(NasirData.getMode()==='api')return state.instructorStudents||[];const ids=new Set(getAssignedStudentIds());return sample.students.filter(x=>ids.has(x.id));}
async function hydrateRoleSchedule(){
 if(NasirData.getMode()!=='api')return;
 const userId=state.userId,role=state.role;
 try{const items=await NasirData.listSchedule(role);if(state.userId!==userId||state.role!==role)return;state.remoteScheduleItems=Array.isArray(items)?items:[];renderPage();}
 catch(error){showToast(error.message||'دریافت برنامه اختصاصی ممکن نشد.');}
}
function schedulePanel(){const items=getScheduleItems();return `<section class="panel schedule-panel"><div class="panel-head"><div><div class="panel-title">${state.role==='instructor'?'برنامه اختصاصی مربی':'جلسات آموزشی من'}</div><div class="panel-subtitle">${state.role==='admin'?'مدیریت و پایش تمام جلسات آموزشگاه':state.role==='instructor'?'فقط هنرجویان و جلسات تخصیص‌یافته به شما':'فقط زمان‌های ثبت‌شده برای پرونده شما'}</div></div><button class="text-link" data-action="schedule">مشاهده تقویم ${icon('arrow')}</button></div><div class="schedule-list">${items.length?items.slice(0,5).map((x)=>`<div class="schedule-row"><div class="schedule-time"><b>${escapeHtml(x.time||'—')}</b><small>${escapeHtml(x.day||'روز جلسه')} · ${dateFa(x.date)}</small></div><div class="schedule-info"><b>${escapeHtml(x.title||'جلسه آموزشی')}</b><span>${escapeHtml(x.desc||'')}</span></div><span class="status ${x.tone||'gray'}">${escapeHtml(x.status||'برنامه‌ریزی‌شده')}</span></div>`).join(''):`<div class="empty-state">${icon('calendar')}${state.role==='admin'?'هنوز جلسه‌ای برای آموزشگاه ثبت نشده است.':state.role==='instructor'?'هنوز جلسه‌ای به حساب مربی شما تخصیص داده نشده است.':'هنوز زمانی برای آموزش شما ثبت نشده است.'}</div>`}</div><div class="panel-footnote">${icon('shield')} برنامه هر کاربر فقط از جلسات متصل به شناسه حساب او ساخته می‌شود.</div></section>`;}
function noticesPanel(){return `<section class="panel"><div class="panel-head"><div><div class="panel-title">آخرین اطلاعیه‌ها</div><div class="panel-subtitle">خبرها و پیام‌های آموزشگاه</div></div><button class="text-link" data-action="announcements">همه اطلاعیه‌ها ${icon('arrow')}</button></div><div class="notice-item"><div class="notice-bullet">${icon('megaphone')}</div><div><b>اطلاعیه برنامه‌ریزی کلاس‌های عملی</b><span>برای هماهنگی جلسات عملی، برنامه هفتگی خود را بررسی کنید.</span></div><time>امروز</time></div><div class="notice-item"><div class="notice-bullet">${icon('book')}</div><div><b>آمادگی برای آزمون آیین‌نامه</b><span>مرور نمونه سؤالات و تابلوهای راهنمایی را در برنامه روزانه قرار دهید.</span></div><time>دیروز</time></div></section>`;}
function progressPanel(){return `<section class="panel progress-card"><div class="panel-head"><div><div class="panel-title">وضعیت پیشرفت آموزشی</div><div class="panel-subtitle">بر اساس مراحل پرونده خودتان</div></div><span class="progress-icon">${icon('trend')}</span></div><div class="progress-big">—</div><div class="progress-caption">در حال دریافت وضعیت پرونده</div><div class="progress-track"><span style="width:0%"></span></div><div class="progress-foot"><span>شروع دوره</span><span>اطلاعات اختصاصی شما</span></div><div class="progress-milestones"><span>ثبت‌نام</span><span>مدارک</span><span>آموزش</span><span>آزمون</span></div></section>`;}
function quickPanel(){const items=state.role==='student'?[['schedule','calendar','برنامه کلاس','مشاهده جلسات آینده'],['learning','book','آزمون آزمایشی','تمرین آیین‌نامه'],['payments','wallet','وضعیت مالی','شهریه و پرداخت‌ها'],['caseFile','file','پرونده من','مشاهده روند پرونده']]:state.role==='instructor'?[['schedule','calendar','برنامه امروز','فقط جلسات اختصاص‌یافته به شما'],['myStudents','users','هنرجویان من','فقط هنرجویان تحت آموزش شما'],['reports','clipboard','گزارش جلسات','ثبت و مشاهده گزارش‌های خود'],['profile','user','پروفایل من','اطلاعات حساب مربی']]:[['students','users','هنرجویان','مدیریت پرونده‌ها'],['instructors','car','مربیان','مشاهده کادر آموزشی'],['schedule','calendar','برنامه کلاس','تنظیم زمان جلسات'],['reports','chart','گزارش‌ها','آمار عملکرد آموزشگاه']];return `<section class="panel"><div class="panel-head"><div><div class="panel-title">دسترسی سریع</div><div class="panel-subtitle">میانبر بخش‌های پرکاربرد</div></div></div><div class="quick-grid">${items.map(([page,ico,label,desc])=>`<button class="quick-action" data-action="${page}"><span>${icon(ico)}</span><b>${label}</b><small>${desc}</small><i>${icon('arrow')}</i></button>`).join('')}</div></section>`;}
function welcomeHero(kind,title,desc,meta=''){return `<section class="welcome-hero ${kind}"><div class="welcome-copy"><span class="welcome-kicker">${icon('sparkle')} سامانه هوشمند آموزشگاه نصیرشهر</span><h2>${title}</h2><p>${desc}</p><div class="welcome-meta">${meta||`<span>${icon('calendar')} ${new Intl.DateTimeFormat('fa-IR',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(new Date())}</span><span>${icon('shield')} فضای آزمایشی</span>`}</div></div><div class="welcome-art" aria-hidden="true"><div class="welcome-ring ring-one"></div><div class="welcome-ring ring-two"></div><div class="welcome-car">${icon('car')}</div><span class="welcome-orbit">NASIR</span></div></section>`;}
function journeyPanel(){return `<section class="panel journey-panel"><div class="panel-head"><div><div class="panel-title">مسیر دریافت گواهینامه</div><div class="panel-subtitle">مراحل بر اساس پرونده اختصاصی شما</div></div><button class="text-link" data-action="caseFile">مشاهده پرونده ${icon('arrow')}</button></div><div class="journey-steps"><div class="journey-step"><span>۱</span><b>ثبت‌نام</b><small>در انتظار بررسی</small></div><div class="journey-step"><span>۲</span><b>مدارک</b><small>در انتظار</small></div><div class="journey-step"><span>۳</span><b>آموزش عملی</b><small>در انتظار</small></div><div class="journey-step"><span>۴</span><b>آزمون‌ها</b><small>در انتظار</small></div><div class="journey-step"><span>۵</span><b>پایان دوره</b><small>در انتظار</small></div></div></section>`;}
function learningSnapshot(){return `<section class="panel learning-snapshot"><div class="panel-head"><div><div class="panel-title">مرکز یادگیری</div><div class="panel-subtitle">برای آزمون آیین‌نامه آماده‌تر شوید</div></div><span class="snapshot-icon">${icon('graduation')}</span></div><div class="learning-cards"><button data-action="startQuiz"><span class="learning-icon blue">${icon('book')}</span><b>آزمون آزمایشی</b><small>سنجش آمادگی و مرور پاسخ‌ها</small><i>${icon('arrow')}</i></button><button data-action="learning"><span class="learning-icon gold">${icon('road')}</span><b>تابلوهای راهنمایی</b><small>مرور علائم و دسته‌بندی‌ها</small><i>${icon('arrow')}</i></button></div></section>`;}
function dashboard(){
  if(state.role==='student') return `${pageHead('داشبورد هنرجو','نمای کلی وضعیت آموزشی و خدمات حساب شما.',`<button class="soft-button" data-action="schedule">${icon('calendar')} برنامه من</button>`)}${welcomeHero('student',`سلام ${escapeHtml(state.name)} عزیز!`,`مسیر یادگیری رانندگی را با برنامه‌ریزی منظم ادامه دهید.`,`<span>${icon('badge')} پرونده اختصاصی شما</span><span>${icon('calendar')} ${new Intl.DateTimeFormat('fa-IR',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</span><span class="welcome-live"><i></i> پرونده در حال آموزش</span>`)}${stats([{label:'وضعیت پرونده',value:'—',note:'در حال دریافت پرونده شما',icon:'file',tone:'gold'},{label:'جلسات اختصاص‌یافته',value:'—',note:'زمان‌بندی پرونده شما',icon:'calendar',tone:'blue'},{label:'پیشرفت آموزشی',value:'—',note:'بر اساس مراحل ثبت‌شده',icon:'trend',tone:'green'},{label:'مانده شهریه',value:'—',note:'در حال محاسبه از پرداخت‌های شما',icon:'wallet',tone:'rose'}])}<div class="dashboard-grid">${schedulePanel()}${progressPanel()}</div><div class="dashboard-grid dashboard-extra">${journeyPanel()}${learningSnapshot()}</div><div class="bottom-grid">${noticesPanel()}${quickPanel()}</div>`;
  if(state.role==='instructor') return `${pageHead('داشبورد مربی','برنامه کاری، جلسات امروز و هنرجویان تحت آموزش.')}${welcomeHero('instructor',`روز خوبی داشته باشید، ${escapeHtml(state.name)}!`,'برنامه کاری امروز و گزارش‌های آموزشی خود را از این قسمت مدیریت کنید.',`<span>${icon('car')} مربی آموزش عملی</span><span>${icon('calendar')} ${new Intl.DateTimeFormat('fa-IR',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</span><span class="welcome-live"><i></i> حساب مربی فعال</span>`)}${stats([{label:'جلسات تخصیص‌یافته',value:'—',note:'فقط برنامه شما',icon:'calendar',tone:'gold'},{label:'هنرجویان تحت آموزش',value:'—',note:'هنرجویان اختصاص‌یافته به شما',icon:'users',tone:'blue'},{label:'گزارش‌های ثبت‌شده',value:'—',note:'گزارش‌های حساب شما',icon:'check',tone:'green'},{label:'جلسات بدون گزارش',value:'—',note:'برای پیگیری آموزشی',icon:'clipboard',tone:'rose'}])}<div class="dashboard-grid">${schedulePanel()}<section class="panel instructor-tasks"><div class="panel-head"><div><div class="panel-title">چک‌لیست مربی</div><div class="panel-subtitle">کارهای پیشنهادی امروز</div></div><span class="snapshot-icon">${icon('clipboard')}</span></div><div class="task-row"><span class="task-check done">${icon('check')}</span><div><b>بررسی برنامه کلاس‌ها</b><small>فقط جلسات تخصیص‌یافته به حساب شما</small></div><span class="status green">انجام شد</span></div><div class="task-row"><span class="task-check">۲</span><div><b>ثبت گزارش جلسات</b><small>گزارش‌های آموزشی مربوط به هنرجویان شما</small></div><span class="status gold">در انتظار</span></div><div class="task-row"><span class="task-check">۳</span><div><b>پیگیری پیشرفت هنرجویان</b><small>مرور پیشرفت هنرجویان تخصیص‌یافته</small></div><span class="status gray">برنامه‌ریزی</span></div><button class="soft-button task-button" data-action="reports">${icon('clipboard')} ورود به گزارش جلسات</button></section></div><div class="bottom-grid">${quickPanel()}${noticesPanel()}</div>`;
  return `${pageHead('داشبورد مدیریت','نمای کلی عملکرد، ظرفیت آموزشی و وضعیت پرونده‌های آموزشگاه.',`<button class="primary-button" data-action="addPerson">${icon('plus')} ثبت هنرجوی جدید</button>`)}${welcomeHero('admin','مدیریت یکپارچه آموزشگاه','نمایش سریع شاخص‌های عملیاتی و وضعیت جاری آموزشگاه رانندگی نصیرشهر.',`<span>${icon('shield')} دسترسی مدیریت</span><span>${icon('calendar')} ${new Intl.DateTimeFormat('fa-IR',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(new Date())}</span><span class="welcome-live"><i></i> سامانه در حالت پیش‌نمایش</span>`)}${stats([{label:'هنرجویان ثبت‌شده',value:'—',note:'در حال دریافت پرونده‌ها',icon:'users',tone:'blue'},{label:'مربیان فعال',value:'—',note:'فهرست اعضای آموزشگاه',icon:'car',tone:'green'},{label:'جلسات برنامه‌ریزی‌شده',value:'—',note:'برنامه واقعی آموزشگاه',icon:'calendar',tone:'gold'},{label:'پرونده‌های نیازمند بررسی',value:'—',note:'بر اساس وضعیت پرونده‌ها',icon:'file',tone:'rose'}])}<div class="dashboard-grid admin-overview"><section class="panel"><div class="panel-head"><div><div class="panel-title">نمای نمونه روند ثبت‌نام هفتگی</div><div class="panel-subtitle">تعداد درخواست‌های ثبت‌شده · داده نمایشی</div></div><span class="pill active">۷ روز اخیر</span></div><div class="chart-legend"><span><i></i> ثبت‌نام جدید</span><b>۴۶ پرونده</b></div><div class="bar-chart">${[['ش','38'],['ی','52'],['د','44'],['س','70'],['چ','60'],['پ','88'],['ج','49']].map(([d,h],i)=>`<div class="bar-column"><span style="height:${h}%"></span><small>${d}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">وضعیت پرونده‌ها</div><div class="panel-subtitle">توزیع مراحل آموزشی</div></div>${icon('chart')}</div><div class="stage-summary"><div><span class="stage-dot green"></span><b>در حال آموزش</b><strong>۷۲</strong></div><div><span class="stage-dot gold"></span><b>تکمیل مدارک</b><strong>۱۸</strong></div><div><span class="stage-dot blue"></span><b>در انتظار آزمون</b><strong>۲۶</strong></div><div><span class="stage-dot gray"></span><b>تکمیل‌شده</b><strong>۱۲</strong></div></div><div class="stage-total"><span>مجموع پرونده‌های نمونه</span><b>۱۲۸ پرونده</b></div></section></div><div class="dashboard-grid dashboard-extra"><section class="panel"><div class="panel-head"><div><div class="panel-title">آخرین ثبت‌نام‌ها</div><div class="panel-subtitle">فهرست کوتاه پرونده‌های تازه</div></div><button class="text-link" data-action="students">همه هنرجویان ${icon('arrow')}</button></div><div class="recent-list">${sample.students.slice(0,4).map((x,i)=>`<div class="recent-row"><span class="person-mini">${x.name[0]}</span><div><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.code)} · ${escapeHtml(x.course)}</small></div><span class="status ${i===1?'gold':'green'}">${escapeHtml(x.status)}</span></div>`).join('')}</div></section>${schedulePanel()}</div><div class="bottom-grid">${quickPanel()}${noticesPanel()}</div>`;
}
function schedulePage(){
 const items=getScheduleItems();const admin=state.role==='admin',instructor=state.role==='instructor';
 const title=admin?'برنامه کلاس‌های آموزشگاه':instructor?'برنامه کاری من':'برنامه آموزش من';
 const desc=admin?'مدیریت و تخصیص زمان جلسات به هنرجو و مربی.':instructor?'فقط جلساتی که به شما اختصاص داده شده است.':'زمان جلسات آموزشی مربوط به پرونده خودتان.';
 const actions=admin?`<button class="primary-button" data-action="addSchedule">${icon('calendarPlus')} افزودن جلسه</button>`:'';
 return `${pageHead(title,desc,actions)}
 <section class="panel schedule-calendar"><div class="panel-head"><div><div class="panel-title">تقویم هفتگی</div><div class="panel-subtitle">${instructor?'جلسات اختصاص‌یافته به مربی شما':admin?'برنامه تمام هنرجویان و مربیان':'فقط برنامه اختصاصی شما'} · نمای آزمایشی</div></div><span class="pill active">هفته جاری</span></div><div class="calendar-strip">${(()=>{const now=new Date(),offset=(now.getDay()+1)%7,start=new Date(now);start.setDate(now.getDate()-offset);const days=[];for(let i=0;i<7;i++){const date=new Date(start);date.setDate(start.getDate()+i);const iso=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,label=new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(date),number=new Intl.DateTimeFormat('fa-IR',{day:'numeric'}).format(date),count=items.filter(x=>x.date?String(x.date).slice(0,10)===iso:x.day===label).length;days.push(`<button type="button" class="day-card ${date.toDateString()===now.toDateString()?'today':''}" data-day-index="${i}"><span>${label}</span><b>${number}</b><span>${new Intl.NumberFormat('fa-IR').format(count)} جلسه</span></button>`);}return days.join('');})()}</div></section>
 <div class="schedule-toolbar"><div class="search-box">${icon('search')}<input type="search" placeholder="جست‌وجوی جلسه یا هنرجو..." data-schedule-search></div><select class="filter-select" data-schedule-filter><option value="all">همه وضعیت‌ها</option><option value="green">برگزارشده</option><option value="gold">در انتظار</option><option value="gray">برنامه‌ریزی‌شده</option></select></div>
 <section class="panel"><div class="panel-head"><div><div class="panel-title">${admin?'تمام جلسات':instructor?'جلسات من':'جلسات من'}</div><div class="panel-subtitle">${new Intl.NumberFormat('fa-IR').format(items.length)} جلسه در نمای فعلی</div></div><span class="pill">${admin?'آموزشگاه':instructor?'مربی':'هنرجو'}</span></div><div class="schedule-list schedule-full-list">${items.length?items.map(x=>`<div class="schedule-row"><div class="schedule-time"><b>${escapeHtml(x.time||'—')}</b><small>${escapeHtml(x.day||'روز جلسه')} · ${dateFa(x.date)}</small></div><div class="schedule-info"><b>${escapeHtml(x.title||'جلسه آموزشی')}</b><span>${escapeHtml(x.desc||'')}</span><small class="schedule-extra">${icon('car')} ${escapeHtml(x.vehicle||'خودروی آموزشی')} · ${escapeHtml(x.location||'محدوده آموزشگاه')}</small></div><span class="status ${x.tone||'gray'}">${escapeHtml(x.status||'برنامه‌ریزی‌شده')}</span></div>`).join(''):`<div class="empty-state">${icon('calendar')}${admin?'هنوز جلسه‌ای برنامه‌ریزی نشده است.':instructor?'هنوز جلسه‌ای به شما اختصاص داده نشده است.':'هنوز جلسه‌ای برای پرونده شما ثبت نشده است.'}</div>`}</div></section>`;
}
function peopleTable(type){
 const data=type==='students'?sample.students:sample.instructors,students=type==='students',canAdd=state.role==='admin';
 const title=students?'مدیریت هنرجویان':'مدیریت مربیان';
 const active=data.filter(x=>['فعال','در حال آموزش'].includes(x.status)).length;
 const headers=students?'<th>شماره پرونده</th><th>دوره</th><th>تاریخ ثبت‌نام</th><th>تماس</th><th>نشانی</th><th>شهریه ثبت‌شده</th>':'<th>حوزه فعالیت</th><th>شماره تماس</th>';
 const rows=data.map(x=>students?`<tr data-person-status="${['فعال','در حال آموزش'].includes(x.status)?'active':x.status==='مرخصی'?'leave':'pending'}"><td><div class="person-cell"><span class="person-mini">${escapeHtml((x.name||'؟')[0])}</span><div class="person-detail"><b>${escapeHtml(x.name)}</b><small>${x.nationalId?`کد ملی: ${escapeHtml(x.nationalId)}`:'پرونده آموزشی'}</small></div></div></td><td>${escapeHtml(x.code||'—')}</td><td>${escapeHtml(x.course||'پایه سوم')}</td><td><span class="registration-date-cell">${dateFa(x.registrationDate)}</span></td><td>${escapeHtml(x.phone||'—')}</td><td><span class="admin-address-cell">${escapeHtml([x.province,x.city,x.neighborhood,x.address].filter(Boolean).join('، ')||'ثبت نشده')}</span></td><td>${x.tuitionAmountToman?money(x.tuitionAmountToman):'—'}</td><td><span class="status ${x.status==='فعال'||x.status==='در حال آموزش'?'green':x.status==='مرخصی'?'gray':'gold'}">${escapeHtml(x.status||'در حال بررسی')}</span></td><td><button class="outline-button case-open-button" data-action="openCase" data-student-id="${escapeHtml(x.id)}">${icon('file')} پرونده</button></td></tr>`:`<tr data-person-status="${x.status==='فعال'?'active':x.status==='مرخصی'?'leave':'pending'}"><td><div class="person-cell"><span class="person-mini">${escapeHtml((x.name||'؟')[0])}</span><div class="person-detail"><b>${escapeHtml(x.name)}</b><small>عضو کادر آموزشگاه</small></div></div></td><td>${escapeHtml(x.field||'مربی آموزش عملی')}</td><td>${escapeHtml(x.phone||'—')}</td><td><span class="status ${x.status==='فعال'?'green':x.status==='مرخصی'?'gray':'gold'}">${escapeHtml(x.status||'در حال بررسی')}</span></td><td><button class="outline-button case-open-button" data-action="showInstructor" data-person-id="${escapeHtml(x.id||'')}">${icon('eye')} جزئیات</button></td></tr>`).join('');
 return `${pageHead(title,students?'ثبت‌نام، مشخصات تماس، نشانی و وضعیت پرونده هنرجویان.':'کادر آموزشی، مربیان فعال و اطلاعات تماس.',canAdd?`<button class="primary-button" data-action="${students?'addPerson':'addInstructor'}">${icon('plus')} ${students?'ثبت هنرجوی جدید':'افزودن مربی'}</button>`:'')}
 <div class="people-summary"><div><span>${icon('users')}</span><b>${new Intl.NumberFormat('fa-IR').format(data.length)}</b><small>${students?'هنرجوی ثبت‌شده':'اعضای کادر آموزشی'}</small></div><div><span>${icon('checkCircle')}</span><b>${new Intl.NumberFormat('fa-IR').format(active)}</b><small>فعال در سیستم</small></div><div><span>${icon('clock')}</span><b>${new Intl.NumberFormat('fa-IR').format(data.length-active)}</b><small>نیازمند پیگیری</small></div></div>
 <section class="panel people-panel"><div class="toolbar"><div class="search-box">${icon('search')}<input type="search" placeholder="${students?'جست‌وجو نام، کد پرونده، تلفن، کد ملی یا نشانی...':'جست‌وجو نام یا شماره تماس مربی...'}" data-search-table></div><select class="filter-select" data-table-filter><option value="all">همه وضعیت‌ها</option><option value="active">فعال / در حال آموزش</option><option value="pending">در انتظار / تکمیل مدارک</option><option value="leave">مرخصی</option></select>${students?`<button class="soft-button" data-action="exportStudents">${icon('download')} خروجی CSV</button>`:''}</div>
 <div class="table-wrap"><table><thead><tr><th>${students?'هنرجو':'نام مربی'}</th>${headers}<th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${rows}</tbody></table></div>
 <div class="table-footnote">${icon('shield')} اطلاعات این فهرست از پایگاه محلی آزمایشی خوانده می‌شود. دسترسی واقعی باید در بک‌اند کنترل شود.</div></section>`;
}
function myStudentsPage(){
 const assigned=getAssignedStudents();
 return `${pageHead('هنرجویان تحت آموزش من','فقط هنرجویانی که جلسه آموزشی آن‌ها به شما تخصیص داده شده است.')}<section class="panel"><div class="panel-head"><div><div class="panel-title">فهرست هنرجویان من</div><div class="panel-subtitle">اطلاعات تماس آموزشی و وضعیت جلسات؛ بدون مشاهده مدارک هویتی و امور مالی</div></div><span class="pill active">${new Intl.NumberFormat('fa-IR').format(assigned.length)} هنرجو</span></div><div id="instructorStudentList">${assigned.length?`<div class="table-wrap"><table><thead><tr><th>هنرجو</th><th>دوره</th><th>جلسات اختصاص‌یافته</th><th>اقدام</th></tr></thead><tbody>${assigned.map(st=>{const count=getScheduleItems().filter(x=>x.studentId===st.id).length;return `<tr><td><div class="person-cell"><span class="person-mini">${escapeHtml((st.name||'؟')[0])}</span><div class="person-detail"><b>${escapeHtml(st.name)}</b><small>${escapeHtml(st.code||'')}</small></div></div></td><td>${escapeHtml(st.course||'پایه سوم')}</td><td>${new Intl.NumberFormat('fa-IR').format(count)} جلسه</td><td><button class="outline-button" data-action="addInstructorReport" data-student-id="${escapeHtml(st.id)}">${icon('clipboard')} ثبت گزارش</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state">هنوز هنرجویی به شما تخصیص داده نشده است. پس از برنامه‌ریزی جلسه توسط مدیریت، هنرجو در این فهرست نمایش داده می‌شود.</div>'}</div></section>`;
}
function instructorReportsPage(){return `${pageHead('گزارش جلسات من','گزارش‌هایی که برای جلسات هنرجویان اختصاص‌یافته به خودتان ثبت کرده‌اید.')}<div class="stats-grid" id="instructorReportStats"><article class="stat-card"><div class="stat-text"><span>هنرجویان من</span><strong>—</strong><small>جلسات اختصاص‌یافته</small></div></article><article class="stat-card"><div class="stat-text"><span>گزارش‌های ثبت‌شده</span><strong>—</strong><small>گزارش‌های شما</small></div></article><article class="stat-card"><div class="stat-text"><span>حضور کامل</span><strong>—</strong><small>جلسات حاضر</small></div></article><article class="stat-card"><div class="stat-text"><span>غیبت / تغییر زمان</span><strong>—</strong><small>برای پیگیری</small></div></article></div><section class="panel"><div class="panel-head"><div><div class="panel-title">آخرین گزارش‌های آموزشی</div><div class="panel-subtitle">فقط گزارش‌هایی که توسط حساب مربی شما ثبت شده است</div></div><button class="soft-button" data-action="myStudents">${icon('users')} هنرجویان من</button></div><div id="instructorReportList"><div class="empty-state">در حال دریافت گزارش‌ها...</div></div></section>`;}
async function hydrateInstructorWorkspace(){
 if(state.role!=='instructor'||!['myStudents','reports'].includes(state.page))return;
 const activeUserId=state.userId,activePage=state.page;
 try{
  const assigned=NasirData.getMode()==='api'?await NasirData.listMyAssignedStudents():getAssignedStudents();if(state.role!=='instructor'||state.userId!==activeUserId||state.page!==activePage)return;state.instructorStudents=assigned;
  if(state.page==='myStudents'){
   const host=document.getElementById('instructorStudentList');if(host){host.innerHTML=assigned.length?`<div class="table-wrap"><table><thead><tr><th>هنرجو</th><th>دوره</th><th>جلسات</th><th>اقدام</th></tr></thead><tbody>${assigned.map(st=>{const count=getScheduleItems().filter(x=>x.studentId===st.id).length;return `<tr><td><div class="person-cell"><span class="person-mini">${escapeHtml((st.name||'؟')[0])}</span><div class="person-detail"><b>${escapeHtml(st.name)}</b><small>${escapeHtml(st.studentCode||'')}</small></div></div></td><td>${escapeHtml(st.course||'پایه سوم')}</td><td>${new Intl.NumberFormat('fa-IR').format(count)} جلسه</td><td><button class="outline-button" data-action="addInstructorReport" data-student-id="${escapeHtml(st.id)}">${icon('clipboard')} ثبت گزارش</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state">هنوز هنرجویی به شما اختصاص داده نشده است.</div>';host.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>handleAction(el.dataset.action,el.dataset.studentId)));}}
  if(state.page==='reports'){
   const cases=await Promise.all(assigned.map(st=>NasirData.getInstructorStudentReports(st.id,state.userId).then(c=>({student:st,case:c})).catch(()=>({student:st,case:{practicalSessions:[]}}))));
   if(state.role!=='instructor'||state.userId!==activeUserId||state.page!==activePage)return;const reports=cases.flatMap(({student,case:c})=>(c.practicalSessions||[]).map(x=>({student,session:x}))).sort((a,b)=>String(b.session.date||'').localeCompare(String(a.session.date||'')));
   const stats=document.querySelectorAll('#instructorReportStats .stat-card strong');[assigned.length,reports.length,reports.filter(x=>x.session.attendance==='present').length,reports.filter(x=>x.session.attendance!=='present').length].forEach((v,i)=>{if(stats[i])stats[i].textContent=new Intl.NumberFormat('fa-IR').format(v);});
   const host=document.getElementById('instructorReportList');if(host)host.innerHTML=reports.length?`<div class="case-item-list">${reports.slice(0,30).map(({student,session})=>`<div class="case-record"><div><b>${escapeHtml(student.name)} · ${escapeHtml(session.topic||'جلسه عملی')}</b><span>${dateFa(session.date)} · ${escapeHtml(session.time||'')} · ${new Intl.NumberFormat('fa-IR').format(Number(session.durationMinutes)||60)} دقیقه</span><small>${escapeHtml(session.notes||'')}</small></div><em class="status ${session.attendance==='present'?'green':session.attendance==='absent'?'rose':'gray'}">${session.attendance==='present'?'حاضر':session.attendance==='absent'?'غایب':'تغییر زمان'}</em></div>`).join('')}</div>`:'<div class="empty-state">هنوز گزارشی توسط شما ثبت نشده است.</div>';
  }
 }catch(error){showToast(error.message||'بارگذاری فضای کاری مربی انجام نشد.');}
}

function learningPage(){return `${pageHead('آموزش آیین‌نامه','محتوای تمرینی و مرور مباحث برای آمادگی آزمون.',`<button class="primary-button" data-action="startQuiz">${icon('book')} شروع آزمون آزمایشی</button>`)}<div class="learning-hero"><div><span class="welcome-kicker">${icon('graduation')} مسیر آمادگی آزمون</span><h2>قدم‌به‌قدم برای آزمون آماده شوید</h2><p>فصل‌ها را مرور کنید، تمرین انجام دهید و نتیجه آزمون‌های آزمایشی خود را پیگیری کنید.</p><button class="soft-button" data-action="startQuiz">شروع یک آزمون ۵ سؤالی ${icon('arrow')}</button></div><div class="learning-hero-icon">${icon('book')}</div></div><div class="learning-stats">${[['تابلوهای راهنمایی','۸ فصل','book'],['قوانین و مقررات','۱۲ درس','file'],['نمونه آزمون','۳۰ سؤال','award'],['مرور اشتباهات','تاریخچه تمرین','check']].map((x,i)=>`<article class="stat-card"><div class="stat-icon ${['gold','blue','green','rose'][i]}">${icon(x[2])}</div><div class="stat-text"><span>${x[0]}</span><strong style="font-size:15px">${x[1]}</strong><small>محتوای نمونه</small></div></article>`).join('')}</div><div class="learning-module-grid">${[['تابلوهای هشداردهنده','شناخت علائم هشدار و خطر','۸ درس','gold','map'],['تابلوهای انتظامی','قوانین ممنوعیت و الزام','۶ درس','blue','shield'],['حق تقدم و تقاطع‌ها','قواعد عبور ایمن از تقاطع','۴ درس','green','road'],['ایمنی و نگهداری خودرو','کنترل‌های اولیه و نکات ایمنی','۵ درس','rose','car']].map((x,i)=>`<article class="learning-module"><span class="learning-icon ${x[3]}">${icon(x[4])}</span><div><b>${x[0]}</b><p>${x[1]}</p><small>${x[2]} · محتوای نمایشی</small></div><button data-action="startQuiz" aria-label="تمرین ${x[0]}">${icon('arrow')}</button></article>`).join('')}</div><div class="notice-banner"><b>یادآوری محتوای آموزشی:</b> پرسش‌ها و درس‌های این نسخه فقط برای تست رابط کاربری هستند و باید با محتوای رسمی و تأییدشده آموزشگاه جایگزین شوند.</div>`;}
function paymentsPage(){
 const admin=state.role==='admin';
 if(!admin)return `${pageHead('شهریه و پرداخت‌های من','مبلغ شهریه، پرداخت‌های تأییدشده و مانده حساب پرونده خودتان را ببینید.',`<button class="primary-button" data-action="requestPayment">${icon('wallet')} اعلام پرداخت / ارسال رسید</button>`)}<section class="panel" id="studentPaymentPanel"><div class="empty-state">در حال دریافت سوابق مالی پرونده...</div></section>`;
 return `${pageHead('امور مالی و دریافت‌ها','ثبت پرداخت هنرجویان، کنترل شهریه و مشاهده مانده هر پرونده.',`<button class="primary-button" data-action="addPayment">${icon('plus')} ثبت دریافت جدید</button><button class="soft-button" data-action="exportPayments">${icon('download')} خروجی گزارش</button>`)}
 <div class="stats-grid" id="adminFinanceStats"><article class="stat-card"><div class="stat-icon gold">${icon('wallet')}</div><div class="stat-text"><span>کل شهریه ثبت‌شده</span><strong>—</strong><small>در حال محاسبه</small></div></article><article class="stat-card"><div class="stat-icon green">${icon('check')}</div><div class="stat-text"><span>مبالغ دریافت‌شده</span><strong>—</strong><small>پرداخت‌های تأییدشده</small></div></article><article class="stat-card"><div class="stat-icon rose">${icon('chart')}</div><div class="stat-text"><span>مانده قابل دریافت</span><strong>—</strong><small>بر اساس شهریه منهای دریافتی</small></div></article><article class="stat-card"><div class="stat-icon blue">${icon('users')}</div><div class="stat-text"><span>پرونده دارای مانده</span><strong>—</strong><small>هنرجویان بدهکار</small></div></article></div>
 <section class="panel"><div class="panel-head"><div><div class="panel-title">وضعیت مالی هنرجویان</div><div class="panel-subtitle">شهریه، مجموع دریافتی و مانده هر پرونده</div></div><span class="pill active" id="financeRecordCount">در حال دریافت اطلاعات</span></div><div class="toolbar"><div class="search-box">${icon('search')}<input id="financeSearch" type="search" placeholder="نام یا شماره پرونده هنرجو..."></div><select id="financeFilter" class="filter-select"><option value="all">همه پرونده‌ها</option><option value="due">دارای مانده</option><option value="settled">تسویه‌شده</option><option value="no-fee">شهریه ثبت‌نشده</option></select></div><div id="financeStudentsTable" class="table-wrap"><div class="empty-state">در حال محاسبه وضعیت مالی پرونده‌ها...</div></div></section>
 <section class="panel"><div class="panel-head"><div><div class="panel-title">آخرین دریافت‌ها</div><div class="panel-subtitle">تراکنش‌های ثبت‌شده در پرونده‌ها</div></div></div><div id="financeRecentPayments" class="payment-list"><div class="empty-state">در حال دریافت تراکنش‌ها...</div></div></section>`;
}
async function hydrateStudentDashboard(){
 if(state.role!=='student'||state.page!=='dashboard')return;
 try{const activeUserId=state.userId;const c=await NasirData.getMyCase(activeUserId);if(state.role!=='student'||state.userId!==activeUserId||state.page!=='dashboard')return;const s=c.student,fee=Number(s.tuitionAmountToman)||Number(c.contracts?.find(x=>x.status!=='cancelled')?.amountToman)||0,paid=(c.payments||[]).filter(x=>!['cancelled','pending'].includes(x.status)).reduce((a,x)=>a+Number(x.amountToman||0),0);const stage=(caseStages.find(x=>x[0]===(s.stage||'registered'))||caseStages[0])[1],idx=Math.max(0,caseStages.findIndex(x=>x[0]===(s.stage||'registered'))),progress=(s.stage==='completed'||s.stage==='archived')?100:Math.round(idx/6*100);const cards=document.querySelectorAll('#contentArea .stats-grid .stat-card strong');const small=document.querySelectorAll('#contentArea .stats-grid .stat-card small');const values=[stage,`${new Intl.NumberFormat('fa-IR').format(getScheduleItems().length)} جلسه`,`${new Intl.NumberFormat('fa-IR').format(progress)}٪`,money(Math.max(0,fee-paid))];values.forEach((v,i)=>{if(cards[i])cards[i].textContent=v;});if(small[1])small[1].textContent='جلسات اختصاص‌یافته به شما';if(small[3])small[3].textContent='مانده براساس پرداخت‌های تأییدشده';const heroMeta=document.querySelector('#contentArea .welcome-meta');if(heroMeta)heroMeta.innerHTML=`<span>${icon('badge')} پرونده ${escapeHtml(s.studentCode||'در انتظار شماره پرونده')}</span><span>${icon('calendar')} ${new Intl.DateTimeFormat('fa-IR',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</span><span class="welcome-live"><i></i> ${escapeHtml(s.status||stage)}</span>`;const big=document.querySelector('#contentArea .progress-big');if(big)big.textContent=`${new Intl.NumberFormat('fa-IR').format(progress)}٪`;const track=document.querySelector('#contentArea .progress-track span');if(track)track.style.width=`${progress}%`;const caption=document.querySelector('#contentArea .progress-caption');if(caption)caption.textContent=`مرحله فعلی: ${stage}`;const stageNodes=document.querySelectorAll('#contentArea .journey-steps .journey-step');const milestones=[{label:'ثبت‌نام',stages:['registered']},{label:'مدارک',stages:['documents_pending','contract_signed']},{label:'آموزش عملی',stages:['training']},{label:'آزمون‌ها',stages:['theory_exam','practical_exam']},{label:'پایان دوره',stages:['completed','archived']}];const current=milestones.findIndex(x=>x.stages.includes(s.stage||'registered'));stageNodes.forEach((node,i)=>{node.classList.toggle('complete',i<current||(s.stage==='completed'||s.stage==='archived'));node.classList.toggle('active',i===current);const small=node.querySelector('small');if(small)small.textContent=(s.stage==='completed'||s.stage==='archived')?'تکمیل‌شده':i<current?'تکمیل‌شده':i===current?'مرحله فعلی':'در انتظار';const num=node.querySelector('span');if(num)num.innerHTML=i<current||(s.stage==='completed'||s.stage==='archived')?icon('check'):String(i+1);});}catch(error){showToast(error.message||'اطلاعات داشبورد هنرجو دریافت نشد.');}
}
async function hydrateInstructorDashboard(){
 if(state.role!=='instructor'||state.page!=='dashboard')return;
 try{const activeUserId=state.userId;const assigned=NasirData.getMode()==='api'?await NasirData.listMyAssignedStudents():getAssignedStudents();if(state.role!=='instructor'||state.userId!==activeUserId||state.page!=='dashboard')return;state.instructorStudents=assigned;const items=getScheduleItems();const sessions=[];for(const student of assigned){const c=await NasirData.getInstructorStudentReports(student.id,state.userId).catch(()=>({practicalSessions:[]}));sessions.push(...(c.practicalSessions||[]));}if(state.role!=='instructor'||state.userId!==activeUserId||state.page!=='dashboard')return;const cards=document.querySelectorAll('#contentArea .stats-grid .stat-card strong');const values=[`${new Intl.NumberFormat('fa-IR').format(items.length)} جلسه`,`${new Intl.NumberFormat('fa-IR').format(assigned.length)} نفر`,new Intl.NumberFormat('fa-IR').format(sessions.length),new Intl.NumberFormat('fa-IR').format(Math.max(0,items.length-sessions.length))];values.forEach((v,i)=>{if(cards[i])cards[i].textContent=v;});const taskRows=document.querySelectorAll('#contentArea .instructor-tasks .task-row');if(taskRows[0])taskRows[0].querySelector('small').textContent=`${new Intl.NumberFormat('fa-IR').format(items.length)} جلسه به حساب شما اختصاص یافته است`;if(taskRows[1])taskRows[1].querySelector('small').textContent=`${new Intl.NumberFormat('fa-IR').format(sessions.length)} گزارش ثبت‌شده · ${new Intl.NumberFormat('fa-IR').format(Math.max(0,items.length-sessions.length))} جلسه بدون گزارش`;if(taskRows[2])taskRows[2].querySelector('small').textContent=`${new Intl.NumberFormat('fa-IR').format(assigned.length)} هنرجوی تخصیص‌یافته`; }catch(_){}
}

async function hydrateAdminDashboard(){if(state.role!=='admin'||state.page!=='dashboard')return;try{const students=await NasirData.listStudents();const statsRoot=document.querySelector('#contentArea .stats-grid');if(!statsRoot)return;const values=[students.length,sample.instructors.filter(x=>x.status==='فعال').length,getScheduleItems().length,students.filter(x=>['registered','documents_pending'].includes(x.stage)).length];const cards=statsRoot.querySelectorAll('.stat-card');values.forEach((v,i)=>{const strong=cards[i]?.querySelector('strong');if(strong)strong.textContent=new Intl.NumberFormat('fa-IR').format(v)+(i===0||i===1?' نفر':i===2?' جلسه':' پرونده');});const counts={training:0,documents_pending:0,theory_exam:0,completed:0};students.forEach(x=>{if(Object.hasOwn(counts,x.stage))counts[x.stage]++;});const stageEls=document.querySelectorAll('#contentArea .stage-summary>div strong');[counts.training,counts.documents_pending,counts.theory_exam,counts.completed].forEach((v,i)=>{if(stageEls[i])stageEls[i].textContent=new Intl.NumberFormat('fa-IR').format(v);});const total=document.querySelector('#contentArea .stage-total b');if(total)total.textContent=`${new Intl.NumberFormat('fa-IR').format(students.length)} پرونده`; }catch(_){}}
async function hydrateStudentPayments(){
 const host=document.getElementById('studentPaymentPanel');if(!host)return;const activeUserId=state.userId;
 try{
  const c=await NasirData.getMyCase(activeUserId);if(state.role!=='student'||state.userId!==activeUserId||state.page!=='payments')return;const s=c.student,fee=Number(s.tuitionAmountToman)||Number(c.contracts?.find(x=>x.status!=='cancelled')?.amountToman)||0;
  const received=(c.payments||[]).filter(x=>!['cancelled','pending'].includes(x.status)).reduce((a,x)=>a+Number(x.amountToman||0),0);
  const pending=(c.payments||[]).filter(x=>x.status==='pending').reduce((a,x)=>a+Number(x.amountToman||0),0),balance=Math.max(0,fee-received);
  host.innerHTML=`<div class="panel-head"><div><div class="panel-title">خلاصه وضعیت حساب</div><div class="panel-subtitle">پرونده ${escapeHtml(s.studentCode||s.code||'')} · ${escapeHtml(s.name)}</div></div><span class="status ${balance?'gold':'green'}">${balance?'دارای مانده':'تسویه‌شده'}</span></div><div class="stats-grid"><article class="stat-card"><div class="stat-text"><span>شهریه توافق‌شده</span><strong>${money(fee)}</strong></div></article><article class="stat-card"><div class="stat-text"><span>پرداخت تأییدشده</span><strong>${money(received)}</strong></div></article><article class="stat-card"><div class="stat-text"><span>مانده حساب</span><strong>${money(balance)}</strong></div></article><article class="stat-card"><div class="stat-text"><span>درخواست در انتظار بررسی</span><strong>${money(pending)}</strong></div></article></div><div class="notice-banner"><b>نحوه ثبت پرداخت:</b> در صورت واریز یا پرداخت حضوری، از دکمه «اعلام پرداخت / ارسال رسید» استفاده کنید. مبلغ فقط پس از تأیید مدیریت به دریافتی قطعی اضافه می‌شود.</div><h3 class="panel-title">سوابق پرداخت و درخواست‌ها</h3><div class="payment-list">${(c.payments||[]).map(p=>`<div class="payment-row"><span class="payment-method">${icon('wallet')}</span><div><b>${escapeHtml(p.paymentType||'پرداخت')}</b><small>${dateFa(p.paymentDate)} · ${escapeHtml(({cash:'نقدی',card:'کارت‌خوان',transfer:'واریز بانکی',online:'آنلاین'})[p.method]||p.method||'—')} ${p.reference?' · پیگیری: '+escapeHtml(p.reference):''}</small></div><strong>${money(p.amountToman)}</strong><span class="status ${p.status==='pending'?'gold':p.status==='cancelled'?'gray':'green'}">${p.status==='pending'?'در انتظار تأیید':p.status==='cancelled'?'لغو شده':'تأیید و دریافت‌شده'}</span></div>`).join('')||'<div class="empty-state">هنوز پرداخت یا درخواست پرداختی ثبت نشده است.</div>'}</div>`;
 }catch(error){host.innerHTML=`<div class="empty-state">دریافت اطلاعات مالی ناموفق بود: ${escapeHtml(error.message)}</div>`;}
}
async function hydrateAdminPayments(){
 const host=document.getElementById('financeStudentsTable');if(!host||state.role!=='admin')return;
 try{
  const students=await NasirData.listStudents();const rows=[],transactions=[];let totalFees=0,totalReceived=0,debtCount=0;
  for(const student of students){let c;try{c=await NasirData.getStudentCase(student.id);}catch(_){c={payments:[],contracts:[]};}
   const contracts=c.contracts||[],payments=c.payments||[];const fee=Number(student.tuitionAmountToman)||Number(contracts.find(x=>x.status!=='cancelled')?.amountToman)||0;const received=payments.filter(x=>!['cancelled','pending'].includes(x.status)).reduce((sum,x)=>sum+Number(x.amountToman||0),0);const balance=Math.max(0,fee-received);totalFees+=fee;totalReceived+=received;if(balance>0)debtCount++;
   rows.push({student,fee,received,balance});payments.forEach(p=>{if(p.status!=='cancelled')transactions.push({student,p});});
  }
  const due=totalFees-totalReceived;const cards=document.querySelectorAll('#adminFinanceStats .stat-card .stat-text strong');[totalFees,totalReceived,Math.max(0,due),debtCount].forEach((v,i)=>{if(cards[i])cards[i].textContent=i===3?new Intl.NumberFormat('fa-IR').format(v)+' نفر':money(v);});
  document.getElementById('financeRecordCount').textContent=`${new Intl.NumberFormat('fa-IR').format(rows.length)} پرونده`;
  const draw=()=>{const q=(document.getElementById('financeSearch')?.value||'').trim().toLowerCase(),filter=document.getElementById('financeFilter')?.value||'all';const visible=rows.filter(r=>{const s=r.student;const text=[s.name,s.studentCode,s.code,s.phone,s.nationalId].join(' ').toLowerCase();return (!q||text.includes(q))&&(filter==='all'||(filter==='due'&&r.balance>0)||(filter==='settled'&&r.fee>0&&r.balance===0)||(filter==='no-fee'&&r.fee===0));});host.innerHTML=`<table><thead><tr><th>هنرجو</th><th>شهریه</th><th>دریافت‌شده</th><th>مانده</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${visible.map(r=>`<tr><td><div class="person-cell"><span class="person-mini">${escapeHtml((r.student.name||'؟')[0])}</span><div class="person-detail"><b>${escapeHtml(r.student.name)}</b><small>${escapeHtml(r.student.studentCode||r.student.code||'')}</small></div></div></td><td>${money(r.fee)}</td><td>${money(r.received)}</td><td><b>${money(r.balance)}</b></td><td><span class="status ${r.fee&&r.balance===0?'green':r.fee?'gold':'gray'}">${r.fee?(r.balance===0?'تسویه‌شده':'دارای مانده'):'شهریه ثبت نشده'}</span></td><td><button class="outline-button" data-finance-student="${escapeHtml(r.student.id)}">${icon('plus')} ثبت دریافت</button></td></tr>`).join('')||'<tr><td colspan="6">موردی پیدا نشد.</td></tr>'}</tbody></table>`;};
  draw();document.getElementById('financeSearch')?.addEventListener('input',draw);document.getElementById('financeFilter')?.addEventListener('change',draw);
  host.addEventListener('click',e=>{const b=e.target.closest('[data-finance-student]');if(b)openAdminPaymentModal(b.dataset.financeStudent);});
  transactions.sort((a,b)=>String(b.p.paymentDate||b.p.createdAt||'').localeCompare(String(a.p.paymentDate||a.p.createdAt||'')));
  const recent=document.getElementById('financeRecentPayments');if(recent){recent.innerHTML=transactions.slice(0,20).map(({student,p})=>`<div class="payment-row"><span class="payment-method">${icon('wallet')}</span><div><b>${escapeHtml(student.name)} · ${escapeHtml(p.paymentType||'پرداخت')}</b><small>${dateFa(p.paymentDate||String(p.createdAt||'').slice(0,10))} · ${escapeHtml(({cash:'نقدی',card:'کارت‌خوان',transfer:'واریز بانکی',online:'آنلاین'})[p.method]||p.method||'—')}</small></div><strong>${money(p.amountToman)}</strong><span class="status ${p.status==='pending'?'gold':p.status==='cancelled'?'gray':'green'}">${p.status==='pending'?'در انتظار تأیید':p.status==='cancelled'?'لغو شده':'دریافت‌شده'}</span>${p.status==='pending'?`<button class="outline-button" data-approve-payment="${escapeHtml(p.id)}">تأیید دریافت</button>`:''}</div>`).join('')||'<div class="empty-state">هنوز پرداختی ثبت نشده است.</div>';recent.querySelectorAll('[data-approve-payment]').forEach(btn=>btn.addEventListener('click',async()=>{btn.disabled=true;try{await NasirData.updatePaymentStatus(btn.dataset.approvePayment,'received',state.userId);showToast('پرداخت تأیید شد و در دریافتی قطعی قرار گرفت.');await hydrateAdminPayments();}catch(error){btn.disabled=false;showToast(error.message||'تأیید پرداخت انجام نشد.');}}));}
  window.__nasirFinanceExport=rows;
 }catch(error){host.innerHTML=`<div class="empty-state">دریافت اطلاعات مالی ناموفق بود: ${escapeHtml(error.message)}</div>`;}
}
function announcementsPage(){return `${pageHead('اطلاعیه‌ها','پیام‌های رسمی، تغییر برنامه و خبرهای آموزشی آموزشگاه.',`<button class="soft-button" data-action="markRead">${icon('check')} علامت‌گذاری همه به‌عنوان خوانده‌شده</button>`)}<section class="panel announcement-list"><div class="announcement-item unread"><span class="announcement-icon gold">${icon('megaphone')}</span><div><div class="announcement-meta"><span>اطلاعیه عمومی</span><time>امروز · ۰۹:۳۰</time></div><b>برنامه‌ریزی جلسات آموزش عملی</b><p>هنرجویان محترم، برای مشاهده زمان جلسات عملی به بخش «برنامه کلاس‌ها» مراجعه کنید. زمان‌های موجود در نسخه آزمایشی هستند.</p><span class="status gold">جدید</span></div></div><div class="announcement-item unread"><span class="announcement-icon blue">${icon('book')}</span><div><div class="announcement-meta"><span>آموزش</span><time>دیروز · ۱۵:۰۰</time></div><b>مرور مباحث آیین‌نامه</b><p>پیشنهاد می‌شود در کنار جلسات عملی، فصل تابلوها و حق تقدم را مرور کنید.</p><span class="status gold">جدید</span></div></div><div class="announcement-item"><span class="announcement-icon green">${icon('calendar')}</span><div><div class="announcement-meta"><span>یادآوری</span><time>۲ روز پیش</time></div><b>همراه داشتن مدارک در مراجعه حضوری</b><p>هنگام مراجعه به آموزشگاه، مدارک و رسیدهای مربوط به پرونده را همراه داشته باشید.</p><span class="status gray">خوانده‌شده</span></div></div></section>`;}
function profilePage(){const profile=state.profile||{};return `${pageHead('پروفایل من','اطلاعات حساب و تصویر پروفایل خود را مدیریت کنید.',`<span class="pill active">حساب آزمایشی</span>`)}<section class="panel profile-main-panel"><div class="profile-card"><div class="profile-avatar-wrap"><div class="profile-avatar" id="profileAvatar" aria-label="تصویر پروفایل">${escapeHtml((state.name||'ن')[0])}</div><label class="profile-avatar-action profile-avatar-add" id="profilePhotoPickButton" for="profilePhotoInput" title="افزودن عکس پروفایل" aria-label="افزودن عکس پروفایل">${icon('plus')}</label><button class="profile-avatar-action profile-avatar-remove" id="removeProfilePhotoButton" type="button" title="حذف عکس پروفایل" aria-label="حذف عکس پروفایل" hidden>${icon('close')}</button><input id="profilePhotoInput" class="profile-photo-input" type="file" accept="image/jpeg,image/png,image/webp" aria-label="انتخاب عکس پروفایل"></div><div class="profile-person-info"><h3>${escapeHtml(state.name)}</h3><p>${roleLabels[state.role]} · شناسه نمایشی ${escapeHtml(state.userId)}</p><div class="profile-badges"><span>${icon('shield')} حساب آزمایشی</span><span>${icon('calendar')} عضو سامانه</span></div><small class="profile-photo-hint">برای افزودن یا تغییر عکس، علامت + را بزنید؛ برای حذف عکس، علامت × را انتخاب کنید. JPG، PNG یا WebP · حداکثر ۸ مگابایت.</small></div><span class="profile-label">پروفایل</span></div><form id="profileEditForm"><div class="form-grid"><div class="field"><label>نام و نام خانوادگی</label><input name="name" required maxlength="60" value="${escapeHtml(state.name)}"></div><div class="field"><label>شماره همراه</label><input name="phone" inputmode="tel" placeholder="مثلاً ۰۹۱۲۱۲۳۴۵۶۷" value="${escapeHtml(profile.phone||'')}"></div><div class="field"><label>ایمیل (اختیاری)</label><input name="email" type="email" placeholder="name@example.com" value="${escapeHtml(profile.email||'')}"></div><div class="field"><label>شماره پرونده / کد پرسنلی</label><input readonly value="${escapeHtml(state.userId)}"></div><div class="field full"><label>نشانی یا توضیحات</label><textarea name="address" rows="3" placeholder="اطلاعات نمایشی برای تست رابط">${escapeHtml(profile.address||'')}</textarea></div></div><div class="form-actions"><button class="primary-button" type="submit">${icon('check')} ذخیره تغییرات نمایشی</button><span class="field-hint">اطلاعات و عکس در این نسخه آزمایشی، در مرورگر همین دستگاه ذخیره می‌شوند.</span></div></form></section>`;}
function reportsPage(){if(state.role==='instructor')return instructorReportsPage();const bars=[['شنبه',42],['یکشنبه',58],['دوشنبه',50],['سه‌شنبه',76],['چهارشنبه',64],['پنجشنبه',92],['جمعه',35]];return `${pageHead('گزارش‌های عملکرد','نمای کلی شاخص‌های آموزشی، جلسات و ثبت‌نام‌ها.',`<button class="soft-button" data-action="exportReport">${icon('download')} دریافت گزارش CSV</button>`)}<div class="report-kpi-grid">${[['نرخ تکمیل جلسات','۹۲٪','check','green'],['میانگین جلسات روزانه','۱۴.۸','calendar','blue'],['پرونده‌های باز','۳۶','file','gold'],['رضایت نمونه','۴.۷ از ۵','star','rose']].map(x=>`<article class="report-kpi"><span class="report-kpi-icon ${x[3]}">${icon(x[2])}</span><div><small>${x[0]}</small><b>${x[1]}</b><em>شاخص نمایشی</em></div></article>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">حجم جلسات در هفته</div><div class="panel-subtitle">مقایسه جلسات برگزارشده · داده نمونه</div></div><span class="pill active">هفتگی</span></div><div class="bar-chart report-chart">${bars.map(([d,h])=>`<div class="bar-column"><span style="height:${h}%"></span><small>${d}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">وضعیت پرونده‌ها</div><div class="panel-subtitle">توزیع مراحل در داده‌های نمونه</div></div></div><div class="stage-summary"><div><span class="stage-dot green"></span><b>در حال آموزش</b><strong>۷۲</strong></div><div><span class="stage-dot gold"></span><b>تکمیل مدارک</b><strong>۱۸</strong></div><div><span class="stage-dot blue"></span><b>آزمون</b><strong>۲۶</strong></div><div><span class="stage-dot gray"></span><b>پایان‌یافته</b><strong>۱۲</strong></div></div></section></div><div class="notice-banner"><b>توضیح گزارش‌ها:</b> تمام اعداد این صفحه برای تست طراحی هستند. در نسخه متصل، گزارش‌ها از پایگاه داده و با سطح دسترسی مناسب دریافت می‌شوند.</div>`;}
