function money(value){return new Intl.NumberFormat('fa-IR').format(Number(value)||0)+' تومان';}
const jalaliFormatter = new Intl.DateTimeFormat('en-US-u-ca-persian-nu-latn',{year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'});
function dateDigitsLatin(value){return String(value||'').replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[٫]/g,'.').trim();}
function jalaliPartsFromDate(date){const parts=jalaliFormatter.formatToParts(date);const value={};for(const part of parts){if(['year','month','day'].includes(part.type))value[part.type]=Number(part.value);}return value;}
function isoDateParts(value){const match=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})/);return match?{year:Number(match[1]),month:Number(match[2]),day:Number(match[3])}:null;}
function toFaDigits(value){return String(value).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[Number(d)]);}
function isoToJalali(value){const parts=isoDateParts(value);if(!parts)return '';try{const date=new Date(Date.UTC(parts.year,parts.month-1,parts.day,12));const j=jalaliPartsFromDate(date);return `${toFaDigits(j.year)}/${toFaDigits(String(j.month).padStart(2,'0'))}/${toFaDigits(String(j.day).padStart(2,'0'))}`;}catch(_){return '';}}
function jalaliYearStart(jy){const gYear=jy+621;const from=Date.UTC(gYear,2,19,12),to=Date.UTC(gYear,3,3,12);for(let time=from;time<=to;time+=86400000){const date=new Date(time);const j=jalaliPartsFromDate(date);if(j.year===jy&&j.month===1&&j.day===1)return time;}throw new Error('سال شمسی معتبر نیست.');}
function jalaliToIso(value){const clean=dateDigitsLatin(value).replace(/[.-]/g,'/');const match=clean.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);if(!match)throw new Error('تاریخ را به‌شکل سال/ماه/روز وارد کنید؛ نمونه: ۱۴۰۵/۰۹/۰۳.');const jy=Number(match[1]),jm=Number(match[2]),jd=Number(match[3]);if(jy<1200||jy>1600||jm<1||jm>12||jd<1)throw new Error('تاریخ شمسی واردشده معتبر نیست.');const start=jalaliYearStart(jy),next=jalaliYearStart(jy+1);const maxDay=jm<=6?31:jm<=11?30:(next-start)/86400000-336;if(jd>maxDay)throw new Error('روز واردشده در این ماه وجود ندارد.');const offset=jm<=6?(jm-1)*31+jd-1:jm<=11?186+(jm-7)*30+jd-1:336+jd-1;const date=new Date(start+offset*86400000);return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`;}
const JALALI_MONTH_NAMES=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
const JALALI_WEEKDAY_SHORT=['ش','ی','د','س','چ','پ','ج'];
function todayJalaliParts(){const parts=new Intl.DateTimeFormat('en-US-u-ca-persian-nu-latn',{year:'numeric',month:'numeric',day:'numeric',timeZone:'Asia/Tehran'}).formatToParts(new Date());const result={};for(const part of parts)if(['year','month','day'].includes(part.type))result[part.type]=Number(part.value);return result;}
function todayIso(){const p=todayJalaliParts();return jalaliToIso(`${p.year}/${p.month}/${p.day}`);}
function jalaliMonthLength(year,month){if(month<=6)return 31;if(month<=11)return 30;const start=jalaliYearStart(year),next=jalaliYearStart(year+1);return (next-start)/86400000-336;}
function jalaliCalendarData(year,month){if(!Number.isInteger(year)||year<1200||year>1600||!Number.isInteger(month)||month<1||month>12)throw new Error('ماه یا سال شمسی معتبر نیست.');const firstIso=jalaliToIso(`${year}/${month}/1`);const first=isoDateParts(firstIso);const weekday=new Date(Date.UTC(first.year,first.month-1,first.day,12)).getUTCDay();const leading=(weekday+1)%7;const count=jalaliMonthLength(year,month);return {year,month,leading,days:Array.from({length:count},(_,i)=>({day:i+1,iso:jalaliToIso(`${year}/${month}/${i+1}`)}))};}
function jalaliDateField(name,label,value='',options={}){
 const iso=String(value||'').slice(0,10),manual=options.manual===true;
 const required=options.required?'required':'',readonly=options.readonly?'readonly':'',disabled=options.readonly?'disabled':'';
 const hint=options.hint||(manual?'تاریخ تولد را به‌ترتیب سال، ماه و روز وارد کنید؛ اسلش‌ها خودکار قرار می‌گیرند.':'برای انتخاب تاریخ، روی آیکون تقویم بزنید یا تاریخ شمسی را وارد کنید.');
 const calendarButton=manual?'':`<button type="button" class="jalali-date-icon" data-jalali-date-open aria-label="باز کردن تقویم برای ${escapeHtml(label)}" aria-haspopup="dialog" aria-expanded="false" ${disabled}>${icon('calendar')}</button><div class="jalali-date-picker" data-jalali-picker role="dialog" aria-label="انتخاب تاریخ شمسی" hidden></div>`;
 return `<div class="field jalali-date-field${manual?' is-manual':''}"><label>${label}${options.required?' *':''}</label><div class="jalali-date-control"><input type="text" class="jalali-date-display" data-jalali-date-input="${escapeHtml(name)}" ${manual?'data-jalali-manual="true"':''} inputmode="numeric" autocomplete="off" maxlength="10" placeholder="۱۴۰۵/۰۹/۰۳" value="${escapeHtml(isoToJalali(iso))}" ${required} ${readonly} aria-label="${escapeHtml(label)} به تاریخ شمسی">${calendarButton}</div><input type="hidden" name="${escapeHtml(name)}" data-jalali-date-value value="${escapeHtml(iso)}"><small class="jalali-date-hint">${hint}</small><small class="jalali-date-error" data-jalali-date-error hidden></small></div>`;
}
function formatJalaliDateTyping(value,caretPosition){
 const raw=String(value||''),caret=Math.max(0,Math.min(Number(caretPosition)||raw.length,raw.length));
 const digitCountBefore=dateDigitsLatin(raw.slice(0,caret)).replace(/\D/g,'').length;
 const digits=dateDigitsLatin(raw).replace(/\D/g,'').slice(0,8);
 let formatted=digits;
 if(digits.length>=4){formatted=`${digits.slice(0,4)}/`;if(digits.length>4){formatted+=digits.slice(4,6);if(digits.length>=6){formatted+='/';if(digits.length>6)formatted+=digits.slice(6);}}}
 let nextCaret=0,seen=0;
 while(nextCaret<formatted.length&&seen<Math.min(digitCountBefore,digits.length)){if(/\d/.test(formatted[nextCaret]))seen++;nextCaret++;}
 if(formatted[nextCaret]==='/')nextCaret++;
 return {value:toFaDigits(formatted),caret:nextCaret};
}
function renderJalaliPicker(wrap,year,month){const picker=wrap?.querySelector('[data-jalali-picker]');const hidden=wrap?.querySelector('[data-jalali-date-value]');if(!picker)return;const data=jalaliCalendarData(year,month);const today=todayIso();const selected=hidden?.value||'';const cells=Array.from({length:data.leading},()=>'<span class="jalali-calendar-empty" aria-hidden="true"></span>');for(const item of data.days){const classes=['jalali-calendar-day'];if(item.iso===selected)classes.push('is-selected');if(item.iso===today)classes.push('is-today');cells.push(`<button type="button" class="${classes.join(' ')}" data-jalali-day="${item.day}" aria-label="${toFaDigits(item.day)} ${JALALI_MONTH_NAMES[month-1]} ${toFaDigits(year)}" ${item.iso===selected?'aria-pressed="true"':''}>${toFaDigits(item.day)}</button>`);}picker.dataset.year=String(year);picker.dataset.month=String(month);picker.innerHTML=`<div class="jalali-calendar-head"><button type="button" class="jalali-calendar-nav" data-jalali-prev aria-label="ماه قبل">‹</button><div class="jalali-calendar-caption"><b>${JALALI_MONTH_NAMES[month-1]}</b><span>${toFaDigits(year)}</span></div><button type="button" class="jalali-calendar-nav" data-jalali-next aria-label="ماه بعد">›</button></div><div class="jalali-calendar-weekdays">${JALALI_WEEKDAY_SHORT.map((d,i)=>`<span aria-label="${['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'][i]}">${d}</span>`).join('')}</div><div class="jalali-calendar-days">${cells.join('')}</div><div class="jalali-calendar-footer"><button type="button" data-jalali-today>امروز</button><button type="button" data-jalali-clear>پاک کردن</button></div>`;}
function openJalaliPicker(wrap,input){if(!wrap||input?.readOnly)return;const picker=wrap.querySelector('[data-jalali-picker]');const button=wrap.querySelector('[data-jalali-date-open]');const hidden=wrap.querySelector('[data-jalali-date-value]');let parts;if(hidden?.value){const iso=isoDateParts(hidden.value);if(iso)parts=jalaliPartsFromDate(new Date(Date.UTC(iso.year,iso.month-1,iso.day,12)));}if(!parts)parts=todayJalaliParts();renderJalaliPicker(wrap,parts.year,parts.month);if(picker)picker.hidden=false;wrap.classList.add('is-open');button?.setAttribute('aria-expanded','true');}
function closeJalaliPicker(wrap){const picker=wrap?.querySelector('[data-jalali-picker]');if(picker)picker.hidden=true;wrap?.classList.remove('is-open');wrap?.querySelector('[data-jalali-date-open]')?.setAttribute('aria-expanded','false');}
let jalaliDateGlobalWired=false;
function wireJalaliDateInputs(root){
 if(!root?.querySelectorAll)return;
 if(!jalaliDateGlobalWired){
  jalaliDateGlobalWired=true;
  document.addEventListener('click',event=>{if(event.target?.closest?.('.jalali-date-field'))return;document.querySelectorAll('.jalali-date-picker:not([hidden])').forEach(picker=>closeJalaliPicker(picker.closest('.jalali-date-field')));});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.jalali-date-picker:not([hidden])').forEach(picker=>closeJalaliPicker(picker.closest('.jalali-date-field')));});
 }
 root.querySelectorAll('[data-jalali-date-input]').forEach(input=>{
  if(input.dataset.jalaliWired==='1')return;
  input.dataset.jalaliWired='1';
  const wrap=input.closest('.jalali-date-field'),manual=input.dataset.jalaliManual==='true';
  const hidden=wrap?.querySelector('[data-jalali-date-value]'),error=wrap?.querySelector('[data-jalali-date-error]');
  const button=wrap?.querySelector('[data-jalali-date-open]'),picker=wrap?.querySelector('[data-jalali-picker]');
  const clearError=()=>{if(error){error.textContent='';error.hidden=true;}wrap?.classList.remove('is-invalid');};
  const update=(showError=false)=>{
   const value=input.value.trim();
   if(!value){if(hidden)hidden.value='';input.setCustomValidity(input.required?'تکمیل تاریخ الزامی است.':'');clearError();return true;}
   if(manual){
    const digitCount=dateDigitsLatin(value).replace(/\D/g,'').length;
    if(digitCount!==8){
     if(hidden)hidden.value='';
     const message='تاریخ تولد را کامل و به‌شکل سال/ماه/روز وارد کنید؛ نمونه: ۱۴۰۵/۰۹/۰۳.';
     input.setCustomValidity(message);
     if(error){error.textContent=showError?message:'';error.hidden=!showError;}
     if(showError)wrap?.classList.add('is-invalid');else wrap?.classList.remove('is-invalid');
     return false;
    }
   }
   try{
    const iso=jalaliToIso(value);if(hidden)hidden.value=iso;input.setCustomValidity('');clearError();return true;
   }catch(err){
    if(hidden)hidden.value='';input.setCustomValidity(err.message);
    if(error){error.textContent=(showError||!manual)?err.message:'';error.hidden=manual&&!showError;}
    if(showError||!manual)wrap?.classList.add('is-invalid');else wrap?.classList.remove('is-invalid');
    return false;
   }
  };
  const choose=(iso)=>{if(!iso)return;input.value=isoToJalali(iso);if(hidden)hidden.value=iso;input.setCustomValidity('');clearError();closeJalaliPicker(wrap);input.dispatchEvent(new Event('change',{bubbles:true}));};
  if(manual)input.addEventListener('keydown',event=>{
   if((event.key!=='Backspace'&&event.key!=='Delete')||input.selectionStart!==input.selectionEnd)return;
   const caret=input.selectionStart||0,slashIndex=event.key==='Backspace'?caret-1:caret;
   if(slashIndex<0||input.value[slashIndex]!=='/')return;
   event.preventDefault();
   const digits=dateDigitsLatin(input.value).replace(/\D/g,'').slice(0,8);
   const digitsBefore=dateDigitsLatin(input.value.slice(0,slashIndex)).replace(/\D/g,'').length;
   const removeAt=event.key==='Backspace'?Math.max(0,digitsBefore-1):Math.min(digits.length-1,digitsBefore);
   if(removeAt<0||!digits.length)return;
   const nextDigits=digits.slice(0,removeAt)+digits.slice(removeAt+1);
   const formatted=formatJalaliDateTyping(nextDigits,removeAt);
   input.value=formatted.value;
   try{input.setSelectionRange(formatted.caret,formatted.caret);}catch(_){}
   update(false);
  });
  input.addEventListener('input',()=>{
   if(manual){const formatted=formatJalaliDateTyping(input.value,input.selectionStart);if(input.value!==formatted.value){input.value=formatted.value;try{input.setSelectionRange(formatted.caret,formatted.caret);}catch(_){}}update(false);}
   else update(false);
  });
  input.addEventListener('blur',()=>{if(update(manual)&&hidden?.value)input.value=isoToJalali(hidden.value);});
  if(!manual){
   input.addEventListener('click',()=>openJalaliPicker(wrap,input));
   button?.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();if(picker?.hidden)openJalaliPicker(wrap,input);else closeJalaliPicker(wrap);});
   picker?.addEventListener('click',event=>{
    const prev=event.target.closest('[data-jalali-prev]'),next=event.target.closest('[data-jalali-next]'),day=event.target.closest('[data-jalali-day]'),today=event.target.closest('[data-jalali-today]'),clear=event.target.closest('[data-jalali-clear]');
    if(prev||next){let y=Number(picker.dataset.year),m=Number(picker.dataset.month)+(prev?-1:1);if(m<1){m=12;y--;}if(m>12){m=1;y++;}if(y>=1200&&y<=1600)renderJalaliPicker(wrap,y,m);return;}
    if(day){choose(jalaliToIso(`${picker.dataset.year}/${picker.dataset.month}/${day.dataset.jalaliDay}`));return;}
    if(today){choose(todayIso());return;}
    if(clear){input.value='';if(hidden)hidden.value='';input.setCustomValidity(input.required?'تکمیل تاریخ الزامی است.':'');clearError();closeJalaliPicker(wrap);input.focus();}
   });
  }
  update(false);
 });
}
function dateFa(value){if(!value)return '—';try{const raw=String(value);const date=/^\d{4}-\d{2}-\d{2}/.test(raw)?new Date(`${raw.slice(0,10)}T12:00:00Z`):new Date(raw);return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}).format(date);}catch(_){return value;}}
function caseItemList(items,empty,render){return items&&items.length?`<div class="case-item-list">${items.map(render).join('')}</div>`:`<div class="case-empty">${empty}</div>`;}
function caseSection(title,subtitle,content,extra=''){return `<section class="panel case-panel"><div class="panel-head"><div><div class="panel-title">${title}</div><div class="panel-subtitle">${subtitle}</div></div>${extra}</div>${content}</section>`;}
