 return `<form id="caseProfileForm" class="case-form"><div class="form-grid">${fields.map(([name,label,value,type])=>type==='date'?jalaliDateField(name,label,value,{readonly:!editable,hint:'تاریخ شمسی پرونده',manual:name==='birthDate'}):`<div class="field ${name==='address'?'full':''}"><label>${label}</label><input name="${name}" type="${type}" value="${escapeHtml(value??'')}" ${editable?'':'readonly'}></div>`).join('')}</div>${editable?'<div class="form-actions"><button class="primary-button" type="submit">ذخیره اطلاعات پرونده</button></div>':'<p class="field-hint">برای اصلاح مشخصات، با مدیریت آموزشگاه تماس بگیرید.</p>'}</form>`;
