function openAddPersonModal(){if(state.role!=='admin')return;openModal('ثبت‌نام و تشکیل پرونده هنرجو','اطلاعات هویتی، نشانی، شهریه و مدارک اولیه را در یک فرم ثبت کنید.',studentRegistrationForm(),'addStudentForm');}

function openAdminPaymentModal(preselectedStudentId=''){
 if(state.role!=='admin')return;
 openModal('ثبت دریافت جدید','پرداخت را به پرونده هنرجوی مربوط متصل کنید.',`<form id="adminPaymentForm" class="modal-form"><div class="form-grid"><div class="field full"><label>هنرجو</label><select name="studentId" id="adminPaymentStudent" required><option value="">در حال دریافت فهرست...</option></select></div><div class="field"><label>مبلغ دریافت (تومان)</label><input name="amountToman" type="number" min="1000" step="1000" required placeholder="مبلغ واقعی دریافتی"></div>${jalaliDateField('paymentDate','تاریخ دریافت',todayIso(),{required:true})}<div class="field"><label>روش دریافت</label><select name="method"><option value="cash">نقدی</option><option value="card">کارت‌خوان</option><option value="transfer">واریز بانکی</option><option value="online">آنلاین (فقط پس از تأیید سرور)</option></select></div><div class="field"><label>نوع دریافت</label><select name="paymentType"><option>شهریه</option><option>پیش‌پرداخت شهریه</option><option>هزینه آزمون</option><option>هزینه خدمات</option><option>سایر</option></select></div><div class="field"><label>وضعیت</label><select name="status"><option value="received">وجه دریافت شده</option><option value="pending">در انتظار تأیید</option></select></div><div class="field"><label>شماره رسید / پیگیری</label><input name="reference" placeholder="شماره رسید یا تراکنش"></div><div class="field full"><label>توضیحات</label><textarea name="note" rows="2" placeholder="توضیح تکمیلی"></textarea></div></div><div class="form-actions"><button class="primary-button" type="submit">ثبت در سوابق مالی</button></div><small class="field-hint">ثبت در نسخه محلی فقط برای تست است؛ تأیید پرداخت آنلاین باید سمت سرور انجام شود.</small></form>`,'adminPaymentForm');
 NasirData.listStudents().then(students=>{const select=document.getElementById('adminPaymentStudent');if(!select)return;select.innerHTML='<option value="">انتخاب هنرجو</option>'+students.map(s=>`<option value="${escapeHtml(s.id)}" ${s.id===preselectedStudentId?'selected':''}>${escapeHtml(s.name)} · ${escapeHtml(s.studentCode||s.code||'')}</option>`).join('');}).catch(e=>showToast(e.message||'فهرست هنرجویان دریافت نشد.'));
}
function openStudentPaymentRequestModal(){
 if(state.role!=='student')return;
 NasirData.getMyCase(state.userId).then(c=>{
  const s=c.student,fee=Number(s.tuitionAmountToman)||Number(c.contracts?.find(x=>x.status!=='cancelled')?.amountToman)||0,paid=(c.payments||[]).filter(x=>!['cancelled','pending'].includes(x.status)).reduce((a,x)=>a+Number(x.amountToman||0),0),balance=Math.max(0,fee-paid);
  if(balance<=0){showToast('برای این پرونده مانده شهریه‌ای ثبت نشده است.');return;}
  openModal('اعلام پرداخت برای بررسی','این فرم فقط درخواست یا اعلام واریز ثبت می‌کند. تا تأیید مدیریت، مبلغ در دریافتی قطعی محاسبه نمی‌شود.',`<form id="studentPaymentRequestForm" class="modal-form"><div class="notice-banner"><b>مانده فعلی:</b> ${money(balance)}</div><div class="form-grid"><div class="field"><label>مبلغ پرداخت / واریز شده (تومان)</label><input name="amountToman" type="number" min="1000" max="${balance}" step="1000" required></div>${jalaliDateField('paymentDate','تاریخ پرداخت',todayIso(),{required:true})}<div class="field"><label>روش پرداخت</label><select name="method"><option value="transfer">واریز بانکی</option><option value="card">کارت‌خوان آموزشگاه</option><option value="cash">پرداخت نقدی به آموزشگاه</option></select></div><div class="field"><label>شماره پیگیری / رسید</label><input name="reference" placeholder="کد پیگیری یا شماره رسید"></div><div class="field full"><label>توضیحات</label><textarea name="note" rows="2" placeholder="توضیح تکمیلی (اختیاری)"></textarea></div></div><div class="form-actions"><button class="primary-button" type="submit">ارسال برای تأیید مدیریت</button></div><small class="field-hint">درگاه پرداخت آنلاین در این نسخه فعال نیست؛ اطلاعات این فرم به‌عنوان درخواست در انتظار بررسی ذخیره می‌شود.</small></form>`,'studentPaymentRequestForm');
 }).catch(error=>showToast(error.message||'پرونده مالی دریافت نشد.'));
}
function openInstructorReportModal(studentId){
 if(state.role!=='instructor'||!getAssignedStudentIds().includes(studentId)){showToast('این هنرجو به شما تخصیص داده نشده است.');return;}
 const student=getAssignedStudents().find(x=>x.id===studentId);if(!student){showToast('هنرجو پیدا نشد.');return;}
 openModal('ثبت گزارش جلسه آموزشی',`هنرجو: ${student.name} · گزارش فقط به حساب مربی شما متصل می‌شود.`,`<form id="instructorSessionReportForm" class="modal-form"><input type="hidden" name="studentId" value="${escapeHtml(studentId)}"><div class="form-grid">${jalaliDateField('date','تاریخ جلسه',todayIso(),{required:true})}<div class="field"><label>ساعت شروع</label><input name="time" type="time" value="09:00" required></div><div class="field"><label>مدت جلسه (دقیقه)</label><input name="durationMinutes" type="number" min="15" max="300" step="15" value="60" required></div><div class="field"><label>موضوع آموزش</label><select name="topic"><option>آشنایی با خودرو و کنترل اولیه</option><option>حرکت و توقف</option><option>دنده و کلاچ</option><option>دور دوفرمان</option><option>پارک دوبل</option><option>رانندگی در مسیر شهری</option><option>آمادگی آزمون عملی</option></select></div><div class="field"><label>وضعیت حضور</label><select name="attendance"><option value="present">حاضر</option><option value="absent">غایب</option><option value="rescheduled">تغییر زمان</option></select></div><div class="field full"><label>گزارش و نکات آموزشی</label><textarea name="notes" rows="3" placeholder="مهارت‌های تمرین‌شده، نقاط قوت و موارد نیازمند تمرین"></textarea></div></div><div class="form-actions"><button class="primary-button" type="submit">ثبت گزارش جلسه</button></div></form>`,'instructorSessionReportForm');
}

function openScheduleModal(){
 if(state.role!=='admin')return;
 const studentOptions=sample.students.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)} · ${escapeHtml(x.code||'')}</option>`).join('');
 const instructorOptions=sample.instructors.filter(x=>x.status==='فعال').map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join('');
 openModal('برنامه‌ریزی جلسه جدید','هنرجو و مربی مسئول را مشخص کنید تا هر فرد فقط برنامه مربوط به خودش را ببیند.',`<form id="addScheduleForm" class="modal-form"><div class="form-grid"><div class="field full"><label>عنوان جلسه</label><input name="title" required placeholder="مثلاً تمرین پارک دوبل"></div><div class="field"><label>هنرجو</label><select name="studentId" required>${studentOptions||'<option value="">هنرجویی ثبت نشده</option>'}</select></div><div class="field"><label>مربی مسئول</label><select name="instructorId" required>${instructorOptions||'<option value="">مربی فعالی ثبت نشده</option>'}</select></div><div class="field"><label>روز</label><select name="day"><option>امروز</option><option>شنبه</option><option>یکشنبه</option><option>دوشنبه</option><option>سه‌شنبه</option><option>چهارشنبه</option><option>پنجشنبه</option></select></div><div class="field"><label>ساعت</label><input name="time" type="time" value="14:00" required></div>${jalaliDateField('date','تاریخ',todayIso(),{required:true})}<div class="field"><label>محدوده / محل برگزاری</label><input name="location" value="نصیرشهر"></div><div class="field full"><label>خودرو</label><select name="vehicle"><option>پراید آموزشی</option><option>تیبا آموزشی</option><option>پژو ۲۰۶ آموزشی</option><option>خودروی آموزشی دیگر</option></select></div></div><div class="form-actions"><button class="primary-button" type="submit">ثبت و تخصیص جلسه</button></div><small class="field-hint">این جلسه در برنامه همان هنرجو و مربی نمایش داده می‌شود؛ سایر کاربران به آن دسترسی ندارند.</small></form>`,'addScheduleForm');
}
function openQuizModal(){const questions=[{q:'پیش از حرکت با خودرو، کدام کار اهمیت دارد؟',a:['تنظیم صندلی و آینه‌ها و بستن کمربند','افزایش سرعت موتور','خاموش‌کردن چراغ‌ها'],correct:0},{q:'هنگام نزدیک‌شدن به گذرگاه عابر پیاده چه رفتاری ایمن‌تر است؟',a:['افزایش سرعت','کاهش سرعت و آمادگی برای توقف','استفاده از بوق به‌صورت ممتد'],correct:1},{q:'در هوای بارانی چه تغییری در رانندگی مناسب‌تر است؟',a:['افزایش فاصله طولی','ترمز ناگهانی','حرکت با سرعت بیشتر'],correct:0}];let index=0,score=0;function draw(){const q=questions[index];openModal('آزمون تمرینی نمونه',`سؤال ${index+1} از ${questions.length} · این پرسش‌ها رسمی نیستند.`,`<div class="quiz-progress"><span style="width:${(index/questions.length)*100}%"></span></div><div class="quiz-question"><span class="pill active">سؤال ${index+1}</span><h3>${q.q}</h3><div class="quiz-options">${q.a.map((a,i)=>`<button type="button" data-answer="${i}">${a}</button>`).join('')}</div></div><div class="quiz-result-note">برای ثبت پاسخ، یکی از گزینه‌ها را انتخاب کنید.</div>`);document.querySelectorAll('[data-answer]').forEach(btn=>btn.addEventListener('click',()=>{if(Number(btn.dataset.answer)===q.correct)score++;index++;if(index===questions.length){openModal('نتیجه آزمون',`امتیاز شما: ${score} از ${questions.length}`,`<div class="quiz-finish"><span>${icon('award')}</span><h3>${score===3?'عالی بود!':'تمرین خوبی بود!'}</h3><p>این نتیجه فقط برای تست تعامل آزمون ثبت شده و در پرونده واقعی ذخیره نمی‌شود.</p><button class="primary-button" data-close-modal>بستن آزمون</button></div>`);document.querySelector('[data-close-modal]')?.addEventListener('click',closeModal);}else draw();}));}draw();}
function openPaymentGuide(){openModal('راهنمای وضعیت مالی','اطلاعات پرداخت این نسخه صرفاً نمایشی است.',`<div class="guide-list"><div>${icon('wallet')} <span><b>مبلغ شهریه</b><small>مبلغ توافق‌شده در قرارداد پرونده</small></span></div><div>${icon('checkCircle')} <span><b>مبالغ دریافت‌شده</b><small>فقط پرداخت‌هایی که آموزشگاه تأیید کرده است</small></span></div><div>${icon('shield')} <span><b>تأیید تراکنش</b><small>در نسخه واقعی، تأیید پرداخت باید سمت سرور انجام شود</small></span></div></div>`);}
function downloadCsv(filename,rows){const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportStudentRegister(){const rows=[['نام','شماره پرونده','کد ملی','موبایل','تاریخ ثبت‌نام','استان','شهر','محله','نشانی','دوره','شهریه','وضعیت'],...sample.students.map(s=>[s.name,s.code,s.nationalId,s.phone,dateFa(s.registrationDate),s.province,s.city,s.neighborhood,s.address,s.course,s.tuitionAmountToman,s.status])];downloadCsv('nasir-student-register.csv',rows);showToast('فهرست هنرجویان دریافت شد.');}
function exportPaymentRegister(){const rows=[['هنرجو','شماره پرونده','شهریه','دریافتی','مانده']];(window.__nasirFinanceExport||[]).forEach(r=>rows.push([r.student.name,r.student.studentCode||r.student.code,r.fee,r.received,r.balance]));downloadCsv('nasir-finance-register.csv',rows);showToast('گزارش مالی دریافت شد.');}
function showNotifications(){const panel=document.getElementById('notificationPanel'),button=document.getElementById('notificationButton');if(!state.settings.notifications){showToast('اعلان‌ها در تنظیمات غیرفعال هستند.');return;}const open=panel.classList.contains('hidden');panel.classList.toggle('hidden',!open);button.setAttribute('aria-expanded',String(open));if(open){panel.innerHTML=`<div class="notification-head"><b>اعلان‌های اخیر</b><button class="text-link" type="button" data-open-announcements>مشاهده همه</button></div><div class="notification-entry"><span class="announcement-icon gold">${icon('calendar')}</span><div><b>برنامه کلاس‌ها به‌روزرسانی شد</b><small>امروز · اعلان نمونه</small></div></div><div class="notification-entry"><span class="announcement-icon blue">${icon('file')}</span><div><b>پرونده آموزشی شما در دسترس است</b><small>دیروز · اعلان نمونه</small></div></div>`;panel.querySelector('[data-open-announcements]')?.addEventListener('click',()=>{panel.classList.add('hidden');button.setAttribute('aria-expanded','false');goPage('announcements');});}}
function handleAction(action, studentId){
  if(action==='openCase'){if(state.role!=='admin'&&!(state.role==='student'&&(!studentId||studentId===state.userId))){showToast('دسترسی به این پرونده برای حساب شما مجاز نیست.');return;}state.selectedCaseStudentId=studentId||null;goPage(state.role==='student'?'caseFile':'caseFiles');return;}
  const route=['dashboard','caseFile','caseFiles','schedule','documents','documentArchive','learning','payments','announcements','profile','myStudents','reports','students','instructors','settings'];
  if(route.includes(action)){goPage(action);return;}
  if(action==='addPerson'){if(state.role!=='admin')return;openAddPersonModal();return;}
  if(action==='addInstructor'){if(state.role==='admin')openInstructorModal();else showToast('فقط مدیریت می‌تواند مربی اضافه کند.');return;}
  if(action==='addPayment'){if(state.role==='admin')openAdminPaymentModal();return;}
  if(action==='requestPayment'){if(state.role==='student')openStudentPaymentRequestModal();return;}
  if(action==='addInstructorReport'){if(state.role==='instructor')openInstructorReportModal(studentId);return;}
  if(action==='exportStudents'){exportStudentRegister();return;}
  if(action==='exportPayments'){exportPaymentRegister();return;}
  if(action==='showInstructor'){const person=sample.instructors.find(x=>String(x.id||'')===String(studentId||''))||sample.instructors[0];if(person)openModal('جزئیات مربی', 'اطلاعات نمونه عضو کادر آموزشی.', `<div class="guide-list"><div>${icon('user')}<span><b>${escapeHtml(person.name)}</b><small>نام و نام خانوادگی</small></span></div><div>${icon('phone')}<span><b>${escapeHtml(person.phone||'—')}</b><small>شماره تماس نمایشی</small></span></div><div>${icon('car')}<span><b>${escapeHtml(person.field||'مربی آموزش عملی')}</b><small>حوزه فعالیت</small></span></div><div>${icon('checkCircle')}<span><b>${escapeHtml(person.status||'فعال')}</b><small>وضعیت همکاری</small></span></div></div>`);return;}
  if(action==='addSchedule'){if(state.role==='admin')openScheduleModal();return;}
  if(action==='startQuiz'){openQuizModal();return;}
  if(action==='paymentInfo'){openPaymentGuide();return;}
  if(action==='markRead'){document.querySelectorAll('.announcement-item.unread').forEach(x=>x.classList.remove('unread'));showToast('اعلان‌ها در این پیش‌نمایش خوانده‌شده علامت‌گذاری شدند.');return;}
  if(action==='exportReport'){const rows=[['شاخص','مقدار'],['هنرجویان ثبت‌شده','۱۲۸'],['مربیان فعال','۸'],['کلاس‌های امروز','۱۸'],['نرخ تکمیل جلسات','۹۲ درصد']];const csv='\uFEFF'+rows.map(r=>r.join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='nasir-demo-report.csv';a.click();URL.revokeObjectURL(url);showToast('گزارش نمونه دریافت شد.');return;}
}
let toastTimer;function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}

function selfRegistrationForm(){return `<form id="selfRegistrationForm" class="modal-form registration-modal-form"><div class="registration-intro"><span class="registration-intro-icon">${icon('graduation')}</span><div><span class="registration-intro-kicker">شروع مسیر شما</span><b>فرم ثبت‌نام هنرجو</b><p>اطلاعات را با دقت وارد کنید تا پرونده آموزشی شما تشکیل شود.</p></div><span class="registration-intro-badge">مرحله آغازین</span></div><div class="notice-banner"><b>درخواست ثبت‌نام هنرجو</b> پس از بررسی مدیریت، وضعیت پذیرش و برنامه کلاس‌ها در همین پنل نمایش داده می‌شود.</div><div class="registration-section"><div class="registration-section-title"><b>مشخصات هنرجو</b><small>اطلاعات برای تشکیل پرونده اولیه</small></div><div class="form-grid"><div class="field"><label>نام و نام خانوادگی *</label><input name="name" required minlength="3" placeholder="نام کامل"></div><div class="field"><label>شماره موبایل *</label><input name="phone" required inputmode="tel" placeholder="09xxxxxxxxx"></div><div class="field"><label>کد ملی</label><input name="nationalId" inputmode="numeric" maxlength="10" placeholder="۱۰ رقم"></div>${jalaliDateField('birthDate','تاریخ تولد','',{manual:true})}<div class="field"><label>نام پدر / سرپرست</label><input name="guardianName"></div><div class="field"><label>شماره سرپرست</label><input name="guardianPhone" inputmode="tel"></div><div class="field"><label>استان</label><input name="province" value="تهران"></div><div class="field"><label>شهر</label><input name="city" value="نصیرشهر"></div><div class="field"><label>محله</label><input name="neighborhood" placeholder="نام محله"></div><div class="field"><label>کد پستی</label><input name="postalCode" inputmode="numeric" maxlength="10"></div><div class="field full"><label>نشانی کامل *</label><textarea name="address" rows="2" required placeholder="خیابان، کوچه، پلاک و واحد"></textarea></div><div class="field full"><label>نوع دوره</label><select name="course"><option>پایه سوم</option><option>تمدید آموزش</option><option>خدمات تکمیلی</option></select></div></div></div><div class="registration-section"><div class="registration-section-title"><b>مدارک اولیه (اختیاری)</b><small>مدارک بعداً نیز از پنل هنرجو قابل تکمیل‌اند.</small></div><div class="registration-document-grid">${[['nationalCard','تصویر کارت ملی'],['birthCertificate','شناسنامه'],['portrait','عکس پرسنلی'],['medical','مدرک پزشکی'],['other','سایر مدارک']].map(([k,l])=>registrationDocumentField(k,l)).join('')}</div></div><div class="form-actions"><button class="primary-button" type="submit">ارسال درخواست ثبت‌نام</button></div><small class="field-hint">در نسخه تستی، پرونده محلی ساخته می‌شود. در نسخه واقعی، مدیریت باید درخواست را تأیید کند و ورود با رمز یک‌بارمصرف فعال شود.</small></form>`;}
function openSelfRegistrationModal(){openModal('ثبت‌نام اولیه هنرجو','اطلاعات هویتی و راه‌های ارتباطی را وارد کنید تا پرونده اولیه شما ایجاد شود.',selfRegistrationForm(),'selfRegistrationForm');}
document.getElementById('displayName').value=localStorage.getItem('nasirDemoName')||'';
setProfileVisuals();updateLoginPrompt();
document.getElementById('profileShortcut')?.addEventListener('click',()=>goPage('profile'));
document.getElementById('notificationButton')?.addEventListener('click',e=>{e.stopPropagation();showNotifications();});
document.addEventListener('click',e=>{const p=document.getElementById('notificationPanel');if(p&&!p.classList.contains('hidden')&&!p.contains(e.target)&&!e.target.closest('#notificationButton')){p.classList.add('hidden');document.getElementById('notificationButton')?.setAttribute('aria-expanded','false');}});
document.querySelectorAll('.role-option').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.role-option').forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-pressed',String(x===btn));});updateLoginPrompt();}));
document.getElementById('demoLoginForm').addEventListener('submit',e=>{e.preventDefault();resolveLogin();});
document.getElementById('studentSelfRegisterButton')?.addEventListener('click',()=>openSelfRegistrationModal());
document.getElementById('logoutButton').addEventListener('click',()=>{document.getElementById('appShell').classList.add('hidden');document.getElementById('loginScreen').classList.remove('hidden');closeModal();});
document.getElementById('menuToggle').addEventListener('click',()=>{document.getElementById('sidebar').classList.add('open');document.getElementById('sidebarScrim').classList.add('show');});
document.getElementById('sidebarScrim').addEventListener('click',closeSidebar);
